/* Notes photographs data. Kester Small. */
window.COURSE_NOTE_PHOTOS = {"M1U1":[{"screen":"What is Information Technology?","src":"i_OnI_TNcIv9U.jpg","pack":"M1U1","w":820,"h":462,"alt":"A rack of electronic equipment with indicator lights in a dark room.","cap":"A rack of networking and server equipment. This is the technology half of IT: the hardware and networks that capture, store and move data so people can use it as information.","by":"Tyler","title":"Real world:"},{"screen":"The scope of IT: where it is used","src":"i_U1QWCuJBxYo.jpg","pack":"M1U1","w":820,"h":494,"alt":"Aerial view of the cruise ship terminal and buildings at Saint George's, Grenada.","cap":"The cruise ship terminal at Saint George's, Grenada. Tourism is one sector in the scope of IT, relying on booking, scheduling and payment systems to handle visitors.","by":"Hugh Whyte","title":"Real world:"},{"screen":"The limitations of IT","src":"i_PmBNVq4ninQ.jpg","pack":"M1U1","w":820,"h":548,"alt":"A telephone pole knocked over by a typhoon, with cables lying across the ground.","cap":"A utility pole brought down by a typhoon. IT systems depend on power and connectivity, so when poles and cables fail, computers and networks stop working however advanced they are.","by":"Carl Kho","title":"Real world:"},{"screen":"Computing: the umbrella field","src":"i_PqqJ340jrow.jpg","pack":"M1U1","w":820,"h":547,"alt":"Many open umbrellas in assorted colours seen from above.","cap":"Many coloured umbrellas sheltering under one idea. In the same way, Computer Science, Software Engineering, Computer Engineering, Information Systems and IT all sit under the single umbrella of Computing.","by":"Ricardo Resende","title":"Real world:"},{"screen":"Computer Science","src":"i_fzOITuS1DIQ.jpg","pack":"M1U1","w":820,"h":547,"alt":"A man concentrating on a chess game with the board in soft focus.","cap":"A player planning moves in a game of chess. Like Computer Science, chess rewards finding efficient step-by-step strategies, the same thinking behind designing algorithms.","by":"JESHOOTS.COM","title":"Real world:"},{"screen":"Software Engineering","src":"i_gyrKtgqMChY.jpg","pack":"M1U1","w":820,"h":547,"alt":"Two construction workers reviewing building plans together on a tablet.","cap":"Two builders checking plans before work goes ahead. Software Engineering applies the same discipline to large software systems: agreeing requirements, planning the design and working as a team.","by":"alan boyce","title":"Real world:"},{"screen":"Computer Engineering","src":"i_cA8VTQeHU0c.jpg","pack":"M1U1","w":820,"h":547,"alt":"Close-up of a circuit board with electronic components.","cap":"The inside of a circuit board. Computer Engineering designs hardware like this, where processors, memory and connections must work together with the software that runs on them.","by":"Anne Nygård","title":"Real world:"},{"screen":"Information Systems","src":"i_kfnWOD1Tbp8.jpg","pack":"M1U1","w":820,"h":615,"alt":"A hotel reception desk with wooden furniture and a seating area.","cap":"A hotel reception desk. Information Systems asks how a business like a hotel takes bookings, checks in guests and bills them, then designs technology to support those processes.","by":"Neon Wang","title":"Real world:"},{"screen":"Commonalities and differences between the disciplines","src":"i_Of_m3hMsoAA.jpg","pack":"M1U1","w":820,"h":547,"alt":"Four coworkers smiling around a laptop at a table.","cap":"A team gathered around one laptop. The IT disciplines share common ground in this way: each combines people, hardware, software and data, and their specialists often work together on the same project.","by":"Jud Mackrill","title":"Real world:"},{"screen":"Professional organisations and IEEE","src":"i_yhJVLxcquEY.jpg","pack":"M1U1","w":820,"h":585,"alt":"Yellow and green fibre optic cables neatly connected to network equipment.","cap":"Neatly connected fibre optic cables. Standards set by bodies such as IEEE are what let equipment from different makers plug together and work as one network.","by":"Albert Stoynov","title":"Real world:"},{"screen":"BCS, ACM and AIS","src":"i_6vAjp0pscX0.jpg","pack":"M1U1","w":820,"h":547,"alt":"A speaker on stage addressing a large seated audience.","cap":"A speaker addressing a large audience at a conference. Professional bodies such as BCS, ACM and AIS run conferences where members share research and discuss good practice.","by":"Alexandre Pellaes","title":"Real world:"},{"screen":"IT careers in the Caribbean","src":"i_nApaD08bFAE.jpg","pack":"M1U1","w":820,"h":547,"alt":"Two men working together on a computer motherboard.","cap":"Two technicians repairing a computer motherboard. Hands-on support and repair roles like these are IT careers found wherever organisations rely on working computers.","by":"Ricardo IV Tamayo","title":"Real world:"},{"screen":"Researching IT careers: the CXC activity","src":"i_hWJsOnaWTqs.jpg","pack":"M1U1","w":820,"h":547,"alt":"A stack of newspapers on a wooden table, showing the business section.","cap":"A stack of newspapers open at the business pages. Job adverts in daily papers are one of the sources CXC suggests you use when researching IT careers.","by":"Annie Spratt","title":"Real world:"},{"screen":"Lecture notes: The field of Information Technology","src":"i_-hgJu2ykh4E.jpg","pack":"M1U1","w":820,"h":533,"alt":"A student writing on paper at a desk in a classroom.","cap":"A student making handwritten notes in class. Good lecture notes pull the key ideas of the field of Information Technology into one place for revision.","by":"Jeswin Thomas","title":"Real world:"}],"M1U2":[{"screen":"Why IT has a history, and how to outline it","src":"i_SsDZRqcCfSo.jpg","pack":"M1U2","w":820,"h":547,"alt":"A row of old computers sitting on a desk.","cap":"A row of old computers. Machines like these show why IT has a history: each era of hardware left evidence, which lets us outline developments in order.","by":"Mert Kahveci","title":"Real world:"},{"screen":"Before electronics: calculating aids and mechanical machines","src":"i_cHhbULJbPwM.jpg","pack":"M1U2","w":820,"h":544,"alt":"A multicoloured abacus.","cap":"An abacus, one of the earliest calculating aids. Beads moved along rods record numbers, a simple device that came long before electronic machines.","by":"Crissy Jarvis","title":"Real world:"},{"screen":"Generations of computers: the big picture","src":"i_C2SN-eraguM.jpg","pack":"M1U2","w":820,"h":547,"alt":"A vintage compact personal computer with keyboard and mouse in a museum display.","cap":"An early personal computer kept in a museum. Comparing machines like this with today's devices shows how each generation of computers became smaller, cheaper and more capable.","by":"David Klein","title":"Real world:"},{"screen":"First generation: vacuum tubes (1940s to mid-1950s)","src":"i_dUpnF8v_qrU.jpg","pack":"M1U2","w":820,"h":547,"alt":"A single vintage vacuum tube on a workbench.","cap":"A vacuum tube, the glass component that switched and amplified signals in first generation computers. Tubes were large and hot, which is why early machines filled whole rooms.","by":"Madalozzo","title":"Real world:"},{"screen":"Second generation: transistors (late 1950s to mid-1960s)","src":"i_2jXSnvMRwbc.jpg","pack":"M1U2","w":820,"h":461,"alt":"Small black electronic transistors up close.","cap":"MOSFET transistors, a later type of transistor. Transistors replaced vacuum tubes in the second generation, making computers smaller, cooler and more reliable.","by":"Axel Richter","title":"Real world:"},{"screen":"Third generation: integrated circuits (1964 to 1971)","src":"i_pbKnDOY_pv8.jpg","pack":"M1U2","w":820,"h":547,"alt":"Close-up of a circuit board with an integrated circuit chip.","cap":"A close-up of an integrated circuit on a board. Third generation computers packed many transistors onto one small chip like this, shrinking cost and size.","by":"Bermix Studio","title":"Real world:"},{"screen":"Fourth generation: microprocessors (1971 to the present)","src":"i_c3ZWXOv1Ndc.jpg","pack":"M1U2","w":820,"h":547,"alt":"Close-up of a computer processor chip.","cap":"A modern microprocessor. Fourth generation computers place the whole central processing unit on a single chip, which made personal computers and phones possible.","by":"Christian Wiediger","title":"Real world:"},{"screen":"Categories of computers by size and processing ability","src":"i_klWUhr-wPJ8.jpg","pack":"M1U2","w":820,"h":489,"alt":"Rows of black server racks in a data centre.","cap":"Rows of server racks in a data centre. Large computers like these sit at the powerful end of the categories of computers by size and processing ability.","by":"imgix","title":"Real world:"},{"screen":"How each category developed","src":"i_5477L9Z5eqI.jpg","pack":"M1U2","w":820,"h":546,"alt":"A hurricane seen from space.","cap":"A hurricane seen from space. Forecasting severe weather needs huge calculations, the kind of heavy processing task that has driven the development of the most powerful computer categories.","by":"NASA","title":"Real world:"},{"screen":"History of software (1): from machine code to high-level languages","src":"i_FCHlYvR5gJI.jpg","pack":"M1U2","w":820,"h":547,"alt":"A man programming on a laptop.","cap":"A programmer writing code. Early programmers worked in machine code; high-level languages let people write instructions in a form closer to human language.","by":"Danial Igdery","title":"Real world:"},{"screen":"History of software (2): operating systems, applications and apps","src":"i_Pvck4ScQH9E.jpg","pack":"M1U2","w":820,"h":547,"alt":"A person holding a smartphone.","cap":"A person holding a smartphone. Apps are applications designed for devices like this, the latest stage in the history from operating systems to applications and apps.","by":"Adrien","title":"Real world:"},{"screen":"History of the Internet","src":"i_M5tzZtFCOfs.jpg","pack":"M1U2","w":820,"h":460,"alt":"Network cables plugged into networking equipment.","cap":"Network cables plugged into equipment. The Internet grew from linking computers together through physical connections like these so that data can pass between networks.","by":"Taylor Vick","title":"Real world:"},{"screen":"History of telecommunications","src":"i_9blSF_Ay3MY.jpg","pack":"M1U2","w":820,"h":547,"alt":"A black rotary dial telephone.","cap":"A rotary dial telephone. Landline telephones like this carried voice over wires, an early form of the telecommunications that later grew into mobile and data networks.","by":"Quino Al","title":"Real world:"},{"screen":"Telecommunications in the Caribbean","src":"i_XVDAqsOF8HQ.jpg","pack":"M1U2","w":820,"h":545,"alt":"View of St Georges on the island of Grenada in the Caribbean from the water.","cap":"The harbour town of St George's on the island of Grenada. Island communities in the Caribbean depend on telecommunications to stay connected to each other and to the wider world.","by":"Jamie Tudor","title":"Real world:"},{"screen":"Lecture notes: the history of Information Technology","src":"i_333oj7zFsdg.jpg","pack":"M1U2","w":820,"h":547,"alt":"A person holding a red pen while writing in a book.","cap":"A student writing notes by hand. Condensing the history of IT into short lecture notes, from early calculating aids to modern networks, makes revision for the exam easier.","by":"lilartsy","title":"Real world:"}],"M1U3":[{"screen":"Three words examiners never let you mix up","src":"i_xkArbdUcUeE.jpg","pack":"M1U3","w":820,"h":548,"alt":"A black payment terminal with a long white paper receipt on an orange background.","cap":"A payment terminal printing a receipt. Each sale produces raw data, and the printed receipt is that data organised into information a customer can read and use.","by":"Towfiqu barbhuiya","title":"Real world:"},{"screen":"Data: unprocessed, unorganised and discrete","src":"i_dtkbdE4YKj8.jpg","pack":"M1U3","w":820,"h":548,"alt":"A pile of paper receipts.","cap":"A pile of paper receipts. On their own they are unprocessed, unorganised data: separate facts that tell us little until someone sorts and summarises them.","by":"Duskfall Crew","title":"Real world:"},{"screen":"Qualitative and quantitative data","src":"i_eXcF6L9pEug.jpg","pack":"M1U3","w":820,"h":547,"alt":"A hand holding a pen over a blue clipboard.","cap":"A person recording responses on a clipboard. Surveys collect qualitative data, such as opinions and descriptions, and quantitative data, such as counts and measurements.","by":"Phil Hearing","title":"Real world:"},{"screen":"Detailed and sampled data","src":"i_2oegF67ikOM.jpg","pack":"M1U3","w":820,"h":615,"alt":"A digital thermometer showing a reading of 36.9.","cap":"A thermometer showing one reading. A single reading taken now and then is sampled data, while recording the temperature continuously would give detailed data.","by":"Winel Sutanto","title":"Real world:"},{"screen":"From data to information: processing, format and medium","src":"i_yqaskj8lQBE.jpg","pack":"M1U3","w":820,"h":547,"alt":"A computer screen showing a bar chart.","cap":"A bar chart on a computer screen. Processing turns raw figures into information, and the format and medium, here a chart on a screen, shape how easily people understand it.","by":"1981 Digital","title":"Real world:"},{"screen":"Characteristics of information (1): can you trust it?","src":"i_AGQZprOABgQ.jpg","pack":"M1U3","w":820,"h":462,"alt":"Close-up of a control panel with dials and switches.","cap":"A control panel of dials and switches. Information can only be trusted if it is accurate, reliable and comes from a source, such as a working instrument, that people can depend on.","by":"iSawRed","title":"Real world:"},{"screen":"Characteristics of information (2): is it worth having?","src":"i_zR7nFjjIAWE.jpg","pack":"M1U3","w":820,"h":547,"alt":"A calculator sitting on a pile of banknotes and receipts.","cap":"A calculator on banknotes and receipts for a household budget. Information is worth having when it is relevant, timely and useful enough to justify the effort and cost of producing it.","by":"Jakub Żerdzicki","title":"Real world:"},{"screen":"Characteristics of information (3): protection and access","src":"i_mT7lXZPjk7U.jpg","pack":"M1U3","w":820,"h":547,"alt":"A red padlock resting on a black computer keyboard.","cap":"A padlock on a computer keyboard. Information needs protection, so that only authorised people can see or change it, while those who are allowed can still access it when needed.","by":"FlyD","title":"Real world:"},{"screen":"Knowledge: using information to make decisions","src":"i_2CakbXfm_gM.jpg","pack":"M1U3","w":820,"h":615,"alt":"A control room filled with electronic equipment and screens.","cap":"A control room full of equipment. Operators here turn the information in front of them into knowledge and use it to make decisions.","by":"Dmitrijs Safrans","title":"Real world:"},{"screen":"Data quality and appropriateness of data","src":"i_ynwGXMkpYcY.jpg","pack":"M1U3","w":820,"h":656,"alt":"A thermometer reading about 41 degrees Celsius sitting on a plant.","cap":"A thermometer reading 41 degrees Celsius outdoors. Whether such a figure is good data depends on how and where it was measured, which is the question of data quality and appropriateness.","by":"Jarosław Kwoczała","title":"Real world:"},{"screen":"Differences among data, information and knowledge","src":"i_4zvnt60-pak.jpg","pack":"M1U3","w":820,"h":547,"alt":"A white thermometer showing 36 degrees Celsius.","cap":"A thermometer reading of 36. The number alone is data. Knowing that it is a normal body temperature makes it information, and deciding what to do about it is knowledge.","by":"Matteo Fusco","title":"Real world:"},{"screen":"Worked examples across the Caribbean","src":"i_YW4zhg0iZaM.jpg","pack":"M1U3","w":820,"h":547,"alt":"A silhouetted man sitting by the water mending nets at sunset in Grenada.","cap":"A man mending nets at sunset at Grand Mal, Grenada. Fisherfolk turn data such as weather, tides and catches into information and knowledge to decide when and where to fish.","by":"Hugh Whyte","title":"Real world:"},{"screen":"In the exam: answering SO 1.3 questions","src":"i_v3P_spLsOH0.jpg","pack":"M1U3","w":820,"h":547,"alt":"Students sitting in a modern classroom during a lecture.","cap":"Students in a classroom. In the exam you must define data, information and knowledge precisely and support each definition with a clear example.","by":"Vishnu Mehra","title":"Real world:"},{"screen":"Lecture notes: data, information and knowledge","src":"i_s9CC2SKySJM.jpg","pack":"M1U3","w":820,"h":547,"alt":"A person writing on paper at a wooden table next to a mug.","cap":"A person writing notes at a table. Short revision notes help you keep the differences among data, information and knowledge clear for the exam.","by":"Unseen Studio","title":"Real world:"}],"M1U4":[{"screen":"What is an information source?","src":"i_aT88kga0g_M.jpg","pack":"M1U4","w":820,"h":545,"alt":"Wooden bookshelves filled with books.","cap":"Bookshelves filled with books. A library is a classic information source, a place or resource from which people obtain the information they need.","by":"Peter Herrmann","title":"Real world:"},{"screen":"People as information sources","src":"i_K8uzzu6wBKc.jpg","pack":"M1U4","w":820,"h":548,"alt":"A woman talking with another person across a table.","cap":"Two people in conversation across a table. Asking someone directly is a people source: you get a personal, up-to-date answer and can ask follow-up questions, though it depends on what that person knows.","by":"Centre for Ageing Better","title":"Real world:"},{"screen":"Books and catalogues","src":"i_GelF0x5e--c.jpg","pack":"M1U4","w":820,"h":544,"alt":"Books arranged on shelves.","cap":"Books on a shelf. Books are a traditional printed source, and a catalogue helps you find the right one, but their content is fixed at the time of printing.","by":"Aneta Pawlik","title":"Real world:"},{"screen":"Journals, magazines and newspapers","src":"i_AM-Tkk_dkNU.jpg","pack":"M1U4","w":820,"h":547,"alt":"Magazines displayed on a stand.","cap":"Magazines on a display stand. Journals, magazines and newspapers are periodicals: they are published regularly, so they carry fairly current information on a topic.","by":"Marjan Blan","title":"Real world:"},{"screen":"Libraries","src":"i_ct1NZSUSWUc.jpg","pack":"M1U4","w":820,"h":615,"alt":"A library interior with shelves of books.","cap":"A library with rows of shelved books. A library brings many information sources together in one place and is organised so that users can find them.","by":"Fer Troulik","title":"Real world:"},{"screen":"CD-ROMs and DVDs","src":"i__LyLGhy2UMw.jpg","pack":"M1U4","w":820,"h":547,"alt":"A DVD reflecting light.","cap":"A DVD catching the light. CD-ROMs and DVDs store large amounts of information, including video and sound, on a portable disc that is read by a drive.","by":"Phil Hearing","title":"Real world:"},{"screen":"Electronic databases","src":"i_OHx5zVsv_gY.jpg","pack":"M1U4","w":820,"h":547,"alt":"A librarian using a computer to search a database.","cap":"An archival photograph of a librarian using a computer to search a database. Electronic databases let users search large collections of organised records quickly by keyword.","by":"National Cancer Institute","title":"Real world:"},{"screen":"Web sites","src":"i_KYOLKpeT1hc.jpg","pack":"M1U4","w":820,"h":547,"alt":"A person using a laptop computer.","cap":"A person browsing on a laptop. Web sites are reached through a browser and can hold up-to-date information, but their quality varies and must be checked.","by":"Marta Filipczyk","title":"Real world:"},{"screen":"Blogs and wikis","src":"i_1qn0GnP9kk8.jpg","pack":"M1U4","w":820,"h":615,"alt":"A person writing at a desk with a laptop and notebook.","cap":"A person writing at a desk with a laptop. Blogs are written by individuals and wikis are edited by many contributors, so each needs checking before use.","by":"Vardan Papikyan","title":"Real world:"},{"screen":"Social media","src":"i_8-I-gRB6OOs.jpg","pack":"M1U4","w":820,"h":462,"alt":"A smartphone showing social media applications.","cap":"A smartphone displaying social media apps. Social media spreads information fast, but posts come from anyone and may be biased or unchecked.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Primary and secondary sources","src":"i_73OJLcahQHg.jpg","pack":"M1U4","w":820,"h":547,"alt":"An old family photo album open on a table.","cap":"An old family photo album. Photographs and personal records made at the time are primary sources, while writing that interprets them is a secondary source.","by":"Laura Fuhrman","title":"Real world:"},{"screen":"Advantages and disadvantages of primary and secondary sources","src":"i_K-ZsC7YdJ6Y.jpg","pack":"M1U4","w":820,"h":615,"alt":"Rows of binders on a shelf.","cap":"Binders of stored records on a shelf. Primary sources give original, first-hand material but can be hard to find and interpret; secondary sources are easier to read but are one step removed.","by":"Sear Greyson","title":"Real world:"},{"screen":"How information about an event moves through sources","src":"i_ZDNyhmgkZlQ.jpg","pack":"M1U4","w":820,"h":547,"alt":"A microphone and headphones in a recording setup.","cap":"A microphone and headphones. An event may first be recorded or reported live, then written up in news and later in books, so information passes through several sources.","by":"Will Francis","title":"Real world:"},{"screen":"Traditional versus electronic: the overall comparison","src":"i_C7WtoP8gSNE.jpg","pack":"M1U4","w":820,"h":548,"alt":"A tablet computer on a desk.","cap":"A tablet on a desk. Electronic sources are fast to search and update, while traditional printed sources are fixed but familiar; each has strengths in different situations.","by":"felirbe","title":"Real world:"},{"screen":"Lecture notes: types of information sources","src":"i_Hb6uWq0i4MI.jpg","pack":"M1U4","w":820,"h":547,"alt":"A lecturer presenting to an audience.","cap":"A speaker presenting to an audience. A lecture is itself an information source, and notes taken from it are a record to review alongside other source types.","by":"The Climate Reality Project","title":"Real world:"}],"M1U5":[{"screen":"Class slides: Evaluating information","src":"i_1-aA2Fadydc.jpg","pack":"M1U5","w":820,"h":547,"alt":"A teacher at a whiteboard in a classroom.","cap":"A classroom scene with a presenter at the front. Evaluating information means judging a source before relying on it, not just accepting what is presented.","by":"Quilia","title":"Real world:"},{"screen":"Characteristic or criterion? The key distinction","src":"i_weJ7qyjHYwk.jpg","pack":"M1U5","w":820,"h":535,"alt":"A hand ticking items on a checklist.","cap":"A hand ticking items on a checklist. A criterion is a test you apply to judge a source, like a tick-box; a characteristic is simply a feature the source has.","by":"Jakub Żerdzicki","title":"Real world:"},{"screen":"Availability and cost","src":"i_C8jNJslQM3A.jpg","pack":"M1U5","w":820,"h":547,"alt":"A closed sign hanging on a glass door.","cap":"A closed sign on a glass door. Availability means whether you can actually get a source when you need it, and cost is whether you can afford it.","by":"Tim Mossholder","title":"Real world:"},{"screen":"Currency and amount of detail (depth)","src":"i_nDyyiWOjmmY.jpg","pack":"M1U5","w":820,"h":615,"alt":"An airport departures board showing flight information.","cap":"An airport departures board. Its information is only useful while current, and it gives brief detail about each flight, showing currency and depth as characteristics.","by":"Jakub Żerdzicki","title":"Real world:"},{"screen":"Breadth of coverage: depth versus breadth","src":"i_4iyttj0jh7E.jpg","pack":"M1U5","w":820,"h":547,"alt":"A set of encyclopedia volumes on a shelf.","cap":"Encyclopedia volumes on a shelf. Encyclopedias cover a very wide range of topics in modest detail, which is breadth, while a specialist book goes deep on one topic.","by":"Artur Opala","title":"Real world:"},{"screen":"Reliability","src":"i_3z7Ouv9lpQg.jpg","pack":"M1U5","w":820,"h":544,"alt":"Archival scientific measuring instruments.","cap":"Scientific measuring instruments in an archival photograph. Information from careful measurement by trained people is generally more reliable than unsupported claims.","by":"NOAA","title":"Real world:"},{"screen":"Format and medium","src":"i_fi3_lDi3qPE.jpg","pack":"M1U5","w":820,"h":547,"alt":"Seven-inch vinyl records, 45 rpm singles.","cap":"Seven-inch vinyl singles at 45 rpm. Format is how information is arranged, such as audio, and the medium is what carries it, here vinyl rather than print or disc.","by":"Eric Krull","title":"Real world:"},{"screen":"Comparing sources by their characteristics","src":"i_kpsoe4dYlaU.jpg","pack":"M1U5","w":820,"h":547,"alt":"A small dock on a Caribbean island","cap":"A small dock on a Caribbean island. A place can be described by several different sources, such as a photograph like this, and each source has its own characteristics that can be compared.","by":"Christian Lendl","title":"Real world:"},{"screen":"Criterion 1: Bias","src":"i_Evo4wmtRaPI.jpg","pack":"M1U5","w":820,"h":501,"alt":"A crowd of protesters holding signs.","cap":"A crowd holding signs. Each group presents its own view, so a source can be biased, favouring one side; check who produced it and why.","by":"Alex Radelich","title":"Real world:"},{"screen":"Criteria 2 and 3: Accuracy and completeness","src":"i_WahfNoqbYnM.jpg","pack":"M1U5","w":820,"h":615,"alt":"Various tape measures and rulers.","cap":"Tape measures and rulers. Accuracy means information is correct and exact, like a good measurement; completeness means nothing important has been left out.","by":"William Warby","title":"Real world:"},{"screen":"Criterion 4: Cultural context","src":"i_KB0Ipylp7dc.jpg","pack":"M1U5","w":820,"h":547,"alt":"Two carnival dancers posing for a selfie in Curacao.","cap":"Two carnival dancers posing for a selfie on Curacao. Information is shaped by culture, so a source from one setting may not suit or be understood in another.","by":"Quinten de Graaf","title":"Real world:"},{"screen":"Criterion 5: Currency as a selection test","src":"i_tT2DSShVDTI.jpg","pack":"M1U5","w":820,"h":547,"alt":"A marker pen resting on a wall calendar.","cap":"A marker on a calendar. Currency means how recent information is, so check dates; some topics change quickly and old information can mislead.","by":"Eliza Diamond","title":"Real world:"},{"screen":"Criterion 6: Refereed and un-refereed sources","src":"i__c70Nhh6p44.jpg","pack":"M1U5","w":820,"h":547,"alt":"A black microscope.","cap":"A microscope used in research. Refereed sources are checked by independent experts before publication, while un-refereed sources have not had that review.","by":"Yassine Khalfalli","title":"Real world:"},{"screen":"Criterion 7: Characteristics of information on the Internet","src":"i_40XgDxBfYXM.jpg","pack":"M1U5","w":820,"h":547,"alt":"A blue network cable.","cap":"A blue network cable. The Internet connects countless computers, and anyone can publish on it, so its information varies widely in quality and must be evaluated.","by":"Jordan Harrison","title":"Real world:"},{"screen":"Checking a web page: publisher, approval, updates and links","src":"i_P_5mirRrg0k.jpg","pack":"M1U5","w":820,"h":615,"alt":"A magnifying glass beside a laptop on a marble surface.","cap":"A magnifying glass beside a laptop. Checking a page closely means looking at who published it, whether it was approved, when it was updated and whether links work.","by":"MJ Duford","title":"Real world:"},{"screen":"Lecture notes: characteristics of sources and criteria for selecting them","src":"i_6RTM8EsD1T8.jpg","pack":"M1U5","w":820,"h":547,"alt":"A person writing notes at a desk.","cap":"A person writing notes. Reviewing notes on source characteristics and selection criteria helps you apply them when choosing information for a task.","by":"Kyle Gregory Devaras","title":"Real world:"}],"M1U6":[{"screen":"Class slides: Information processing","src":"i_cPyO3GEYjZ4.jpg","pack":"M1U6","w":820,"h":547,"alt":"People working together at an office desk.","cap":"People working together in an office. Information processing is how an organisation turns collected data into useful information for people to act on.","by":"Centre for Ageing Better","title":"Real world:"},{"screen":"What is information processing?","src":"i_Vs6ip7fsld8.jpg","pack":"M1U6","w":820,"h":547,"alt":"A calculator and a pen on a sheet of paper.","cap":"A calculator and pen on paper. Information processing converts raw data, such as numbers, into meaningful information by working on it.","by":"Aaron Lefler","title":"Real world:"},{"screen":"The information processing cycle","src":"i_Q9y3LRuuxmg.jpg","pack":"M1U6","w":820,"h":545,"alt":"A metal filing cabinet.","cap":"A filing cabinet. In the processing cycle, data is collected, worked on, output and stored, and filing is the storage step that lets it be found again.","by":"Maksym Kaharlytskyi","title":"Real world:"},{"screen":"Why data processing is needed: business and scientific data","src":"i_gKUC4TMhOiY.jpg","pack":"M1U6","w":820,"h":547,"alt":"A white microscope on a table.","cap":"A microscope. Scientific work produces large amounts of measured data that must be processed, just as businesses process sales and records.","by":"Ousa Chea","title":"Real world:"},{"screen":"Manual information processing: characteristics and problems","src":"i_rNxfMnfnenE.jpg","pack":"M1U6","w":820,"h":544,"alt":"An old book with handwriting on its pages.","cap":"An old handwritten record book. Manual processing relies on people writing and checking by hand, which is slow and prone to errors.","by":"Afonso Azevedo Neves","title":"Real world:"},{"screen":"Steps of manual information processing","src":"i_wKfAiJTgyK8.jpg","pack":"M1U6","w":820,"h":545,"alt":"Rows of old labelled filing cabinets.","cap":"Rows of labelled filing cabinets. Manual processing involves collecting, recording, sorting and filing paper records by hand, step by step.","by":"Mike Stoll","title":"Real world:"},{"screen":"Automated data processing: definition, steps and examples","src":"i_8gr6bObQLOI.jpg","pack":"M1U6","w":820,"h":547,"alt":"Orange robotic machines in an industrial factory.","cap":"Orange automatic robots in a factory. Automated processing uses machines following programmed steps to handle large volumes of work with little human effort.","by":"Simon Kadula","title":"Real world:"},{"screen":"Automated processing: benefits and disadvantages","src":"i_EyqUxJuOb1Q.jpg","pack":"M1U6","w":820,"h":414,"alt":"Robotic arms assembling a car chassis on a factory line.","cap":"Robotic arms assembling a car chassis. Automation is fast and consistent, but equipment is costly and can displace workers.","by":"Lilian Do Khac","title":"Real world:"},{"screen":"Manual versus automated processing","src":"i_ShsPFYfRlFQ.jpg","pack":"M1U6","w":820,"h":547,"alt":"Old handwritten church record books.","cap":"Old handwritten church record books. Manual records last and need no power, but they are slow to search; automated systems find and process data much faster.","by":"Mick Haupt","title":"Real world:"},{"screen":"Input: data collection, capture and entry","src":"i_I-SoYkFjVI0.jpg","pack":"M1U6","w":820,"h":663,"alt":"A laboratory worker entering data into a database on a computer.","cap":"An archival photograph of a worker entering data into a computer database. Input is collecting data, capturing it and entering it into the system for processing.","by":"CDC","title":"Real world:"},{"screen":"Input in practice: accuracy and choice of method","src":"i_Gh60UXpcNcs.jpg","pack":"M1U6","w":820,"h":615,"alt":"A person typing on a black keyboard.","cap":"A person typing on a keyboard. Typing errors cause inaccurate data, so the input method should be chosen for accuracy and validated.","by":"Luis Villafranca","title":"Real world:"},{"screen":"Processing: collating and analysing","src":"i_81ikZZG7_AA.jpg","pack":"M1U6","w":820,"h":547,"alt":"A stack of papers marked with colourful sticky tabs.","cap":"A stack of papers marked with coloured tabs. Collating brings related data together and marking it helps in analysing what it shows.","by":"Tanja Tepavac","title":"Real world:"},{"screen":"Processing: sorting and calculating","src":"i_h2aDKwigQeA.jpg","pack":"M1U6","w":820,"h":547,"alt":"A calculator beside a pen on a desk.","cap":"A calculator and pen. Processing includes arranging data in order, called sorting, and doing arithmetic on it, called calculating.","by":"Recha Oktaviani","title":"Real world:"},{"screen":"Output: presenting and dissemination","src":"i_Da9qsu-0a00.jpg","pack":"M1U6","w":820,"h":548,"alt":"A colour ink printer on a table.","cap":"A printer on a table. Output presents processed information, here on paper, and can then be shared with those who need it.","by":"Jakub Żerdzicki","title":"Real world:"},{"screen":"Storage: storing and retrieving","src":"i_5utYi64hnJ0.jpg","pack":"M1U6","w":820,"h":462,"alt":"White archive boxes stacked on shelves","cap":"Archive boxes on shelves keep records in an organised place. Storage in an information system works the same way: data is stored so that it can be found and retrieved later.","by":"Luke Caunt","title":"Real world:"},{"screen":"Transmitting information","src":"i_4_Ha_neGOEY.jpg","pack":"M1U6","w":820,"h":547,"alt":"A man on a scooter carrying a box marked Delivery","cap":"A rider carrying a box marked Delivery. Moving goods or documents from one place to another is a physical form of transmitting; information systems transmit information from sender to receiver in the same way, by post, courier or network.","by":"Nurulloh A.A","title":"Real world:"},{"screen":"Feedback: closing the loop","src":"i_0ZUoBtLw3y4.jpg","pack":"M1U6","w":820,"h":548,"alt":"Yellow rating stars","cap":"Star ratings are a familiar kind of feedback. Responses like these flow back into a system so that its output can be reviewed and improved, closing the loop.","by":"Towfiqu barbhuiya","title":"Real world:"},{"screen":"What is an information system?","src":"i_UaMMROu5fq0.jpg","pack":"M1U6","w":820,"h":547,"alt":"Cash registers with monitors at a shop checkout","cap":"Cash registers with monitors at a checkout. Each sale is captured as input, processed into totals and receipts, stored, and output. A shop till is an everyday information system that turns raw data into useful information.","by":"Allen Y","title":"Real world:"},{"screen":"Examples of manual and automated information systems","src":"i_Ph4ZJrwf4x8.jpg","pack":"M1U6","w":820,"h":547,"alt":"A hand pulling a card from a library card catalogue drawer","cap":"A hand pulling a card from a library card catalogue. This is a manual information system: people file, search and retrieve the records by hand. An automated version would do the same job using a computer database.","by":"Daniel Forsman","title":"Real world:"},{"screen":"Advantages of automated information systems","src":"i_H-n8347I6P0.jpg","pack":"M1U6","w":820,"h":462,"alt":"A senior couple on a video call with family","cap":"A senior couple on a video call with family. Automated systems make information fast, accurate and available across distances, so people can communicate instantly instead of waiting for letters or travelling to meet.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Activity: build a manual filing system","src":"i_3DgB223OUZs.jpg","pack":"M1U6","w":820,"h":547,"alt":"A stack of white cards on a wooden surface","cap":"A stack of plain white cards. In the activity you build a manual filing system from cards like these, deciding how to label, order and store each one so that any record can be found again quickly.","by":"Declan Sun","title":"Real world:"},{"screen":"Comparing retrieval and sorting: what the activity shows","src":"i_VwqMTcsb0Tg.jpg","pack":"M1U6","w":820,"h":615,"alt":"A stopwatch","cap":"A stopwatch. Timing how long it takes to retrieve a card from sorted and unsorted piles gives evidence for the activity: a well-organised, sorted system makes retrieval much faster than searching through a random pile.","by":"William Warby","title":"Real world:"},{"screen":"Lecture notes: Information processing","src":"i_N_nunvZZG88.jpg","pack":"M1U6","w":820,"h":547,"alt":"An old handwritten diary with columns of notes","cap":"An old handwritten diary. Records like this were collected, stored and later read back by hand, which is information processing without a computer: data is gathered, organised and kept so it can be turned into useful information.","by":"Nick Russill","title":"Real world:"}],"M1U7":[{"screen":"Why representation matters","src":"i_9qQTUYm4ss4.jpg","pack":"M1U7","w":820,"h":547,"alt":"An airport departures board showing flight information","cap":"An airport departures board. Flight details are shown as a table of times, codes and gates because that format is quick to read. The way information is represented decides how easily people understand it.","by":"JESHOOTS.COM","title":"Real world:"},{"screen":"Data types: character, string and numeric","src":"i_KIh0geVUqnM.jpg","pack":"M1U7","w":820,"h":547,"alt":"A vehicle licence plate close up","cap":"A vehicle licence plate. It mixes letters and digits in one value, like a string. Systems must decide whether to treat such a value as text or as a number, because that affects how it is stored and used.","by":"Tory Hoffman","title":"Real world:"},{"screen":"Aural and visual data","src":"i_sT0n-Ie8OKo.jpg","pack":"M1U7","w":820,"h":547,"alt":"A podcast microphone in a recording setup","cap":"A podcast microphone. Spoken words are aural data, information heard rather than seen. Visual data, such as photographs and charts, reaches us through the eyes. Computers can capture and store both kinds.","by":"Robinson Recalde","title":"Real world:"},{"screen":"Information as text, graphics and tables","src":"i_tuJ3tXSayco.jpg","pack":"M1U7","w":820,"h":547,"alt":"The finance section of a newspaper filled with columns of numbers","cap":"The finance section of a newspaper. The same information can be shown as text, as a table of figures or as a graphic. Choosing the right form helps readers find and understand what matters.","by":"Annie Spratt","title":"Real world:"},{"screen":"Graphical representations: graphs and charts","src":"i_XrIfY_4cK1w.jpg","pack":"M1U7","w":820,"h":547,"alt":"A newspaper page showing a stock chart","cap":"A newspaper page showing a stock chart. A line graph turns many numbers into one shape, so a reader can see a trend at a glance. That is the purpose of graphs and charts.","by":"Markus Spiske","title":"Real world:"},{"screen":"Signals: analogue and digital","src":"i_GTIutdltrkA.jpg","pack":"M1U7","w":820,"h":626,"alt":"A vinyl record spinning on a turntable","cap":"A vinyl record on a turntable. The groove carries sound as a continuously varying wave, which is an analogue signal. Digital audio instead stores sound as separate numeric samples made of 0s and 1s.","by":"Andrea Cipriani","title":"Real world:"},{"screen":"Sound and video as information","src":"i_H3C5ZmTcoDw.jpg","pack":"M1U7","w":820,"h":547,"alt":"A man speaking into a microphone in a radio studio","cap":"A presenter speaking into a microphone in a radio studio. His voice is captured as sound information and can be recorded, edited, stored and broadcast, just as video can be.","by":"Geoff Moore","title":"Real world:"},{"screen":"Special-purpose notations: mathematical and scientific","src":"i_5mZ_M06Fc9g.jpg","pack":"M1U7","w":820,"h":615,"alt":"Formulas written on an old blackboard","cap":"Formulas written on a blackboard. Mathematical notation packs complex ideas into compact symbols that specialists can read quickly. It is a special-purpose notation designed for one field.","by":"Roman Mager","title":"Real world:"},{"screen":"Musical notation and musical symbols","src":"i_BFcN8o_kzks.jpg","pack":"M1U7","w":820,"h":547,"alt":"Piano sheet music on a music stand","cap":"Sheet music on a piano. Notes, staves and symbols record pitch and rhythm so any trained musician can reproduce the sound. It is a special-purpose notation for representing music on paper.","by":"Miguel Alcântara","title":"Real world:"},{"screen":"Morse Code","src":"i_sJsFEnp_bfk.jpg","pack":"M1U7","w":820,"h":474,"alt":"An antique Morse Register device on a wooden base","cap":"An antique Morse Register made by L. G. Tillotson & Co., New York, in 1870. Machines like this recorded messages as patterns of short and long signals, an early way of encoding text for transmission.","by":"The New York Public Library","title":"Real world:"},{"screen":"Binary: bits, bytes and place values","src":"i_U8XpuqGEO0I.jpg","pack":"M1U7","w":820,"h":547,"alt":"A white light switch on a blue wall","cap":"A light switch has two states, on and off. A bit has two states in the same way, 1 or 0. Computers combine huge numbers of these two-state parts to store and process data.","by":"Steve A Johnson","title":"Real world:"},{"screen":"Converting denary to binary","src":"i_ynfmVbvunQU.jpg","pack":"M1U7","w":820,"h":645,"alt":"A light switch on a wall","cap":"A wall light switch has two states, on and off. Binary works the same way, using only 1 (on) and 0 (off) to represent any denary number.","by":"Isabella Fischer","title":"Real world:"},{"screen":"ASCII: representing characters in binary","src":"i_vP3pnOoCiYE.jpg","pack":"M1U7","w":820,"h":647,"alt":"Vintage typewriter keys","cap":"Vintage typewriter keys, each showing one character. A computer keyboard works similarly: each key press is converted to a binary code, and ASCII is the agreed table that links each character to its code.","by":"Johnny Briggs","title":"Real world:"},{"screen":"Lecture notes: representing data and information","src":"i_xcvXS6wDCAY.jpg","pack":"M1U7","w":820,"h":547,"alt":"A woman's hands at a desk writing in a notebook","cap":"A person writing notes in a blank notebook. Writing is one way of representing ideas in a form others can read. This unit covers the many forms data can take, from text and symbols to binary.","by":"Kelly Sikkema","title":"Real world:"}],"M1U8":[{"screen":"What counts as a tool in IT?","src":"i_1N5jjLyBafc.jpg","pack":"M1U8","w":820,"h":547,"alt":"A toolbox with wrenches and other hand tools","cap":"A toolbox of wrenches. A tool extends what a person can do with a specific job in mind. In IT, tools are the devices and software, such as a modem or a messaging app, used to handle information.","by":"Alexander Schimmeck","title":"Real world:"},{"screen":"Hardware tools: the modem","src":"i_tN344soypQM.jpg","pack":"M1U8","w":820,"h":514,"alt":"An internet modem and router taken in an office","cap":"An internet modem and router in an office. This hardware converts signals between a computer network and the telephone, cable or fibre line, which is how a home or business connects to the Internet.","by":"Stephen Phillips","title":"Real world:"},{"screen":"Software tools: advantages and disadvantages","src":"i_JhevWHCbVyw.jpg","pack":"M1U8","w":820,"h":547,"alt":"A hand using a calculator at a desk","cap":"A hand using a calculator at a desk. Tools that automate calculation are fast and accurate, which is the kind of advantage software offers. Disadvantages include cost, the need for training, and errors if the user enters wrong data.","by":"Towfiqu barbhuiya","title":"Real world:"},{"screen":"Communication tools: real-time or asynchronous?","src":"i_4SNUcHPiC8c.jpg","pack":"M1U8","w":820,"h":547,"alt":"A black corded telephone","cap":"A corded telephone. A phone call is real-time communication because both people take part at the same moment. Email and messages are asynchronous, because the reply can come later.","by":"Quino Al","title":"Real world:"},{"screen":"Online services and search engines","src":"i_utWyPB8_FU8.jpg","pack":"M1U8","w":820,"h":547,"alt":"A hand pressing the keypad of a cash machine","cap":"A hand using a cash machine keypad. Banking is an everyday service that runs over a network. Online services let people complete tasks and find information remotely, and search engines help them locate that information.","by":"Eduardo Soares","title":"Real world:"},{"screen":"VoIP and SMS","src":"i_zo43vop2Iuk.jpg","pack":"M1U8","w":820,"h":547,"alt":"A headset on a table beside a notebook computer","cap":"A headset beside a notebook computer, set up for calls over the Internet. VoIP carries voice as data over a network instead of a traditional phone line, which is how call centres often work.","by":"Siwawut Phoophinyo","title":"Real world:"},{"screen":"Forums, message boards and mailing lists","src":"i_9PXnqrIKYW8.jpg","pack":"M1U8","w":820,"h":608,"alt":"A corkboard covered with flyers and notices","cap":"A corkboard covered in flyers and notices. Anyone can post and read at their own time, which is how an online forum or message board works, with a topic and replies left for others to find later.","by":"Zoshua Colah","title":"Real world:"},{"screen":"Telnet and FTP (upload/download)","src":"i_vSprjjDbu60.jpg","pack":"M1U8","w":820,"h":462,"alt":"Close-up of a server in a server room","cap":"A server in a server room. FTP lets users upload files to, and download files from, a remote computer like this one, while Telnet lets them log in and run commands on it from a distance.","by":"Tyler","title":"Real world:"},{"screen":"Social media tools","src":"i_y2pvFL57Qnk.jpg","pack":"M1U8","w":820,"h":547,"alt":"People using smartphones inside a train","cap":"People using smartphones on a train. Social media tools let users share, react and keep in touch from anywhere. They are a quick way to reach many people but can also distract and spread false information.","by":"John Lockwood","title":"Real world:"},{"screen":"Web-conferencing and cross-platform messaging tools","src":"i_smgTvepind4.jpg","pack":"M1U8","w":820,"h":615,"alt":"A laptop showing a group video call next to a coffee cup","cap":"A laptop showing a group video call. Web-conferencing tools let people in different places meet face to face on screen, share content and talk in real time without travelling.","by":"Chris Montgomery","title":"Real world:"},{"screen":"Comparing the Internet tools","src":"i_bKDOZ7neVl4.jpg","pack":"M1U8","w":820,"h":547,"alt":"A person browsing electronics in a brightly lit store","cap":"A shopper browsing electronics. Choosing between products means comparing them on the same criteria. Comparing Internet tools works the same way: look at cost, speed, reach and ease of use side by side.","by":"Bhanu Singh","title":"Real world:"},{"screen":"How to justify a tool choice","src":"i_rtD_lcsN6_U.jpg","pack":"M1U8","w":820,"h":547,"alt":"A group of people sitting around a table with laptops","cap":"A group around a table with laptops, discussing business plans. Teams decide which tool to use by weighing options and giving reasons. Justifying a choice means linking it to the needs of the task and users.","by":"Lyubomyr Reverchuk","title":"Real world:"},{"screen":"Case study: choosing tools for a Caribbean business","src":"i_miWvkqLXxGw.jpg","pack":"M1U8","w":820,"h":547,"alt":"A blue shop front with goods on display","cap":"A small blue shop with goods on display. A business like this must choose affordable tools, such as a phone, messaging and online listing, that suit its customers. The case study asks you to make and justify such choices.","by":"Asael Peña","title":"Real world:"},{"screen":"Lecture notes: Tools used in Information Technology","src":"i_pUAM5hPaCRI.jpg","pack":"M1U8","w":820,"h":547,"alt":"A white work table with a notebook, smartphone and laptop","cap":"A desk with a laptop, a smartphone and a notebook. Each is a tool used in information technology, from hardware to communication devices, and together they show the range of tools covered in this unit.","by":"JESHOOTS.COM","title":"Real world:"}],"M2U1":[{"screen":"Class slides: Information Technology Systems","src":"i_ZfRXaTHKEu0.jpg","pack":"M2U1","w":820,"h":547,"alt":"Computer equipment and screens in a work setting","cap":"Computer equipment at work in a real setting. Information technology systems combine hardware, software, data and people to carry out tasks like this.","by":"Rodrigo Rodrigues","title":"Real world:"},{"screen":"What is an information system?","src":"i_DkIWsB3dds4.jpg","pack":"M2U1","w":820,"h":547,"alt":"A store checkout counter","cap":"A store checkout is an everyday information system. It collects data about purchases, processes it and produces information such as totals and receipts.","by":"David Trinks","title":"Real world:"},{"screen":"Information systems support operations or decisions","src":"i_5txln04Cx7I.jpg","pack":"M2U1","w":820,"h":462,"alt":"Business professionals discussing reports at a table in a meeting","cap":"Colleagues discussing reports in a meeting. Information systems help staff run daily operations and give managers the information they need to make decisions, such as the ones being discussed here.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Transaction Processing Systems (TPS)","src":"i_FbespiO-VQ8.jpg","pack":"M2U1","w":820,"h":547,"alt":"A customer making a contactless card payment at a coffee shop","cap":"A customer paying by card at a coffee shop. Each payment is a transaction the system records straight away. Transaction processing systems handle the routine, repeated events of a business, such as sales.","by":"SumUp","title":"Real world:"},{"screen":"Management Information Systems (MIS)","src":"i_9PwLeZA-RGc.jpg","pack":"M2U1","w":820,"h":547,"alt":"A person holding a printed report over a laptop","cap":"A person checking a printed report beside a laptop. A management information system summarises stored transaction data into regular reports like this one, helping managers monitor how the business is performing.","by":"Jakub Żerdzicki","title":"Real world:"},{"screen":"Office Automation and Knowledge Work Systems","src":"i_57UZ1obpS2M.jpg","pack":"M2U1","w":820,"h":547,"alt":"A woman working at a desk with a laptop and a red folder","cap":"A worker at a desk with a laptop and folder. Office automation systems support everyday tasks such as documents and email, while knowledge work systems help specialists create and share new information.","by":"Zulfugar Karimov","title":"Real world:"},{"screen":"Decision Support Systems (DSS)","src":"i_bf9sZBcGQl4.jpg","pack":"M2U1","w":820,"h":462,"alt":"A computer screen showing an analytics dashboard with data","cap":"A screen showing an analytics dashboard. Decision support systems analyse data and present results like these so that managers can compare options and make better decisions.","by":"1981 Digital","title":"Real world:"},{"screen":"Executive Information Systems (EIS)","src":"i_JKUTrJ4vK00.jpg","pack":"M2U1","w":820,"h":547,"alt":"Performance graphs and charts displayed on a laptop screen.","cap":"A laptop showing summary graphs of performance. An Executive Information System presents key figures like these at a glance, so senior managers can spot trends without reading detailed records.","by":"Luke Chesser","title":"Real world:"},{"screen":"Extension: data warehouses","src":"i_2JJ3wBHu4_0.jpg","pack":"M2U1","w":820,"h":547,"alt":"A rack of servers in a server room.","cap":"Racks of servers in a server room. A data warehouse is held on large storage systems like these, collecting data from many sources over many years so it can be analysed.","by":"Kevin Ache","title":"Real world:"},{"screen":"Expert systems","src":"i_tl447mekwuQ.jpg","pack":"M2U1","w":820,"h":535,"alt":"A smiling doctor in a white coat talking to a patient in a clinic.","cap":"A doctor consulting a patient in a clinic. An expert system captures this kind of specialist knowledge, asking questions and applying rules to suggest a diagnosis, as a human expert would.","by":"National Cancer Institute","title":"Real world:"},{"screen":"Personnel: who uses which system?","src":"i_AQmrXDDwiQE.jpg","pack":"M2U1","w":820,"h":547,"alt":"Supermarket workers wearing masks and aprons at a service counter.","cap":"Staff at a supermarket service counter. Different personnel use different systems: counter staff use transaction processing, while managers use information systems built from the same data.","by":"Adhitya Sibikumar","title":"Real world:"},{"screen":"Major input and output of each type of IS","src":"i_-gkndM1GvSA.jpg","pack":"M2U1","w":820,"h":547,"alt":"A point-of-sale payment machine","cap":"A point-of-sale machine takes input (the amount and the customer's payment) and gives output (a confirmation and receipt), typical of a transaction processing system.","by":"Simon Kadula","title":"Real world:"},{"screen":"Reports: detailed, summarised, exception and ad hoc","src":"i_heiYgqp0Tsk.jpg","pack":"M2U1","w":820,"h":548,"alt":"An office desk with a smartphone and printed financial charts.","cap":"Financial charts and figures on an office desk. Reports present data in different forms, such as detailed, summarised or exception reports, so managers can make decisions.","by":"Jakub Żerdzicki","title":"Real world:"},{"screen":"The six components of an information system","src":"i_hwiKaoCIGbo.jpg","pack":"M2U1","w":820,"h":547,"alt":"A tablet scanning a barcode","cap":"A tablet scanning a barcode brings hardware, software, data and a person together in one task, showing how the components of an information system work as a whole.","by":"Toon Lambrechts","title":"Real world:"},{"screen":"Information systems add databases and procedures to IT","src":"i_BNBA1h-NgdY.jpg","pack":"M2U1","w":820,"h":545,"alt":"Brown cardboard boxes stacked on a white metal rack.","cap":"Boxes organised on a storage rack. A database works like this, with data stored in an organised structure, and procedures are the agreed steps for finding and using it correctly.","by":"CHUTTERSNAP","title":"Real world:"},{"screen":"How the components relate to one another","src":"i_GmvH5v9l3K4.jpg","pack":"M2U1","w":820,"h":547,"alt":"Interlocking cogs","cap":"Interlocking cogs turn together, each depending on the others. The components of an information system relate in the same way, so a fault in one affects the rest.","by":"Tim Mossholder","title":"Real world:"},{"screen":"Lecture notes: information systems and their components","src":"i_uOhBxB23Wao.jpg","pack":"M2U1","w":820,"h":547,"alt":"Two colleagues discussing ideas at a whiteboard.","cap":"Two colleagues discussing data at a whiteboard. Information systems exist to help people like these turn data into decisions, which is the theme of these lecture notes.","by":"ThisisEngineering","title":"Real world:"}],"M2U2":[{"screen":"Class slides: Information Technology Systems","src":"i_LKySOH0mr38.jpg","pack":"M2U2","w":820,"h":547,"alt":"Students working at computers in a bright school computer lab.","cap":"Students working at computers in a school computer lab. An IT system is the hardware, software, data and people that together let learners do tasks like this.","by":"Haseeb Modi","title":"Real world:"},{"screen":"What is an IT system?","src":"i_NzxypW_bg1M.jpg","pack":"M2U2","w":820,"h":547,"alt":"People working at a video control desk with several monitors and audio equipment","cap":"People operating a control desk with several monitors and audio equipment. An IT system joins hardware, software and people to carry out a purpose like this.","by":"AMONWAT DUMKRUT","title":"Real world:"},{"screen":"Hardware: purpose and the system view","src":"i_ma3ypTuD88Y.jpg","pack":"M2U2","w":820,"h":547,"alt":"A close-up of a circuit board.","cap":"A close-up of a circuit board. Hardware means the physical parts of a computer, and this board shows how components are connected into one working system.","by":"Sven Alleblas","title":"Real world:"},{"screen":"Input devices","src":"i_-NPqKSDydY0.jpg","pack":"M2U2","w":820,"h":547,"alt":"A woman at a front desk scanning a product with a barcode scanner.","cap":"A staff member scanning a product with a barcode scanner. A scanner is an input device: it reads the barcode and sends the data to the computer, as at a shop checkout.","by":"Vagaro","title":"Real world:"},{"screen":"Output devices","src":"i_4pNYr-ftf3g.jpg","pack":"M2U2","w":820,"h":548,"alt":"Two computer monitors on a desk.","cap":"Two computer monitors on a desk. A monitor is an output device, turning the results of processing into text and images that a person can see.","by":"Duskfall Crew","title":"Real world:"},{"screen":"Processing devices: CPU, GPU and motherboard","src":"i_azQILbRXDWU.jpg","pack":"M2U2","w":820,"h":547,"alt":"A close-up of PC components including a CPU cooler, graphics card and motherboard.","cap":"A close-up of the inside of a PC showing the CPU cooler, graphics card and motherboard. These processing devices do the calculations and connect all the other components.","by":"Mehan Talukder","title":"Real world:"},{"screen":"The processor (CPU)","src":"i_tTurhPw9bwQ.jpg","pack":"M2U2","w":820,"h":547,"alt":"A close-up of a computer chip on a printed circuit board.","cap":"A processor chip on a circuit board. The CPU carries out program instructions by fetching, decoding and executing them, and it is the main processing component of a computer.","by":"Bermix Studio","title":"Real world:"},{"screen":"Primary storage: RAM, ROM and cache","src":"i_lYxQ5F9xBDM.jpg","pack":"M2U2","w":820,"h":547,"alt":"A macro photograph of a computer RAM module.","cap":"A close-up of a RAM module. RAM is primary storage: it holds the programs and data currently in use, so the processor can reach them quickly.","by":"Liam Briese","title":"Real world:"},{"screen":"Secondary storage devices","src":"i_xEK3FiK6H3o.jpg","pack":"M2U2","w":820,"h":615,"alt":"An external hard drive with a brushed stainless steel case.","cap":"An external hard drive. Secondary storage like this keeps programs and data permanently, even when the computer is switched off.","by":"Siyuan Hu","title":"Real world:"},{"screen":"Peripheral devices","src":"i_xDNGytM3A5c.jpg","pack":"M2U2","w":820,"h":547,"alt":"A black computer keyboard beside a black computer mouse on a desk.","cap":"A keyboard and mouse on a desk. Peripheral devices like these connect to the computer from outside to add input or output.","by":"Clifford","title":"Real world:"},{"screen":"Software: purpose and the big picture","src":"i_bK5t_WPETow.jpg","pack":"M2U2","w":820,"h":462,"alt":"People working at computers in a brightly lit university computer lab.","cap":"People working at computers in a computer lab. Software is the set of programs that tells the hardware what to do, and every task in a lab like this depends on it.","by":"sunrise University","title":"Real world:"},{"screen":"Application software","src":"i_8wLZi9OhsWU.jpg","pack":"M2U2","w":820,"h":548,"alt":"A calculator beside a laptop","cap":"A calculator and a laptop on a desk. Application software, such as a spreadsheet, helps users complete specific tasks like calculating figures.","by":"Jakub Żerdzicki","title":"Real world:"},{"screen":"Extension: proprietary versus open-source software","src":"i_MnPWB-ybjHQ.jpg","pack":"M2U2","w":820,"h":547,"alt":"A group of people sitting around a laptop computer.","cap":"A group gathered around one laptop. Open-source software is built and improved by communities who share the code openly, while proprietary software is owned and controlled by one company.","by":"Fatemeh Rezvani","title":"Real world:"},{"screen":"Operating systems","src":"i_UTRtBYRVwaY.jpg","pack":"M2U2","w":820,"h":462,"alt":"A computer desk with a monitor, keyboard and sunflower.","cap":"A desktop computer ready for use. The operating system is the software that starts up first and manages the hardware so that other programs can run on it.","by":"Bedirhan Gül","title":"Real world:"},{"screen":"Language translators: compiler, interpreter, assembler","src":"i_p5VW_ZUon7o.jpg","pack":"M2U2","w":820,"h":547,"alt":"A wooden block with the word translation on it.","cap":"A block spelling out the word translation. Language translators do the same job for code: compilers, interpreters and assemblers convert programs into machine code the processor can run.","by":"Ling App","title":"Real world:"},{"screen":"Utilities","src":"i_0thCnM7Wkik.jpg","pack":"M2U2","w":820,"h":615,"alt":"Assorted colourful hand tools.","cap":"A set of hand tools. Utility software is a toolkit in the same way, with small programs for maintaining and protecting a computer, such as backup and virus scanning.","by":"Paul Rosenthal","title":"Real world:"},{"screen":"Embedded systems: monitoring and control","src":"i_fSLI8RdCdyk.jpg","pack":"M2U2","w":820,"h":547,"alt":"A white and grey wall thermostat showing a temperature.","cap":"A wall thermostat. It contains an embedded system that monitors the temperature with a sensor and controls the heating, with no human needed once it is set.","by":"Erik Mclean","title":"Real world:"},{"screen":"Embedded systems: one job done well, and the risk of connection","src":"i_wZkwwYajgOw.jpg","pack":"M2U2","w":820,"h":568,"alt":"A close-up of a microwave oven's buttons and number display.","cap":"A microwave oven's control panel. An embedded system performs this one job well, timing and controlling the heating, but cannot run other programs like a general computer.","by":"Compagnons","title":"Real world:"},{"screen":"Activity: interview an office computer user","src":"i_pg2eJwNVpvY.jpg","pack":"M2U2","w":820,"h":462,"alt":"A woman in glasses interviewing a man at an office desk.","cap":"An interview at an office desk. In this activity you will ask an office computer user questions in the same way, to find out which hardware and software they use daily.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Lecture notes: hardware and software","src":"i_ereEoYDIl20.jpg","pack":"M2U2","w":820,"h":547,"alt":"A teacher guiding students working on a computer in a classroom.","cap":"A teacher guiding students at a computer. These notes summarise the hardware and software you have studied, which you can apply hands-on in the classroom.","by":"Poddar Group of Institutions","title":"Real world:"}],"M2U3":[{"screen":"Class slides: Human-Computer Interaction: Types of Interfaces","src":"i_ls4tzBf86ok.jpg","pack":"M2U3","w":820,"h":547,"alt":"A hand holding a tablet.","cap":"A hand holding a tablet. The way a person gives instructions to a device, here by touch, is the interface, and these slides compare the different types.","by":"Egor Komarov","title":"Real world:"},{"screen":"Why data and information matter","src":"i_V_isgW3g-DE.jpg","pack":"M2U3","w":820,"h":547,"alt":"A man arranging cleaning supplies on shelves in a store.","cap":"A worker arranging stock in a store. Accurate data about what is on the shelves becomes information when it tells managers what to reorder and when.","by":"Adhitya Sibikumar","title":"Real world:"},{"screen":"The three decision-making levels","src":"i_RbYg6fKSfcY.jpg","pack":"M2U3","w":820,"h":462,"alt":"A group of people sitting around a table in a meeting.","cap":"A group meeting around a table. Organisations make decisions at three levels, operational, tactical and strategic, and a meeting like this is typical of the higher levels.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Nature and structure of information at each level","src":"i_qwtCeJ5cLYs.jpg","pack":"M2U3","w":820,"h":590,"alt":"A data reporting dashboard displayed on a laptop screen.","cap":"A reporting dashboard on a laptop. The information needed at each level differs, with detailed figures for operations and summarised trends for senior managers.","by":"Stephen Dawson","title":"Real world:"},{"screen":"Structured, semi-structured and unstructured decisions","src":"i_o-6GhmpELnw.jpg","pack":"M2U3","w":820,"h":547,"alt":"A group of women sitting around a table working on a project.","cap":"A team working through a project together. Semi-structured and unstructured decisions need human judgement and discussion like this, unlike structured decisions that follow fixed rules.","by":"Sable Flow","title":"Real world:"},{"screen":"Linking decision types to decision levels","src":"i_bMWHu8wU1Vk.jpg","pack":"M2U3","w":820,"h":547,"alt":"A computer screen full of data.","cap":"A screen full of data. Different decision types need different information, and this mapping shows which systems supply it to operational, tactical and strategic managers.","by":"1981 Digital","title":"Real world:"},{"screen":"What is HCI?","src":"i_7IHHoNL1otQ.jpg","pack":"M2U3","w":820,"h":388,"alt":"Airport check-in counters","cap":"Airport check-in counters are designed around how people interact with them. HCI studies how the design of such systems affects how easily people can use them.","by":"Edwin Petrus","title":"Real world:"},{"screen":"Command line interfaces","src":"i_07bxCZgKY-k.jpg","pack":"M2U3","w":820,"h":426,"alt":"A black laptop computer keyboard.","cap":"A computer keyboard. A command line interface is operated entirely by typing exact commands on a keyboard, with no menus or icons to point at.","by":"Alexander Sinn","title":"Real world:"},{"screen":"Menu-driven interfaces","src":"i_ceapPR3kGK0.jpg","pack":"M2U3","w":820,"h":547,"alt":"A menu board listing drinks and salads.","cap":"A menu board with drinks and salads listed. A menu-driven interface works the same way: the user picks from a list of options instead of typing commands.","by":"Jerry Wei","title":"Real world:"},{"screen":"Form-based interfaces","src":"i_N3o-leQyFsI.jpg","pack":"M2U3","w":820,"h":547,"alt":"Pens lying near a sheet of white paper.","cap":"Pens beside a blank sheet of paper. A form-based interface follows the same idea as a paper form, with labelled fields to fill in one by one.","by":"Kelly Sikkema","title":"Real world:"},{"screen":"Graphical user interfaces (GUI)","src":"i_WOgCbmxdbg4.jpg","pack":"M2U3","w":820,"h":547,"alt":"A computer monitor sitting on a wooden desk.","cap":"A desktop monitor on a wooden desk. A graphical user interface shows windows, icons and menus on a screen like this, controlled with a pointer.","by":"Nubelson Fernandes","title":"Real world:"},{"screen":"Icons: functions as pictures","src":"i_a30TpsTN1_4.jpg","pack":"M2U3","w":820,"h":559,"alt":"Street signs indicating directions for cars and motorcycles.","cap":"Road signs that use pictures to give directions. Icons on a computer work in the same way, a small picture that stands for a function so users understand it quickly.","by":"Zero Vo","title":"Real world:"},{"screen":"Direct manipulation interfaces","src":"i_LRzkT1gIU8A.jpg","pack":"M2U3","w":820,"h":547,"alt":"A man pointing with a finger at an information touchscreen.","cap":"A man touching an information screen with his finger. A direct manipulation interface lets users act on objects on screen directly, by touching or dragging them.","by":"Kate Trysh","title":"Real world:"},{"screen":"Natural language interfaces","src":"i_9TF54VdG0ws.jpg","pack":"M2U3","w":820,"h":547,"alt":"A small smart speaker on a white surface with its lights on.","cap":"A smart speaker listening for a spoken request. A natural language interface lets people give commands in ordinary speech instead of learning special commands.","by":"Kevin Bhagat","title":"Real world:"},{"screen":"Speech interfaces","src":"i_uxtt10wTK2U.jpg","pack":"M2U3","w":820,"h":433,"alt":"A woman talking on a mobile phone","cap":"A woman speaking into a mobile phone. Speech interfaces let people control a device with their voice instead of a keyboard or touch screen.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"The right interface depends on the user","src":"i_cHbyGVOQspk.jpg","pack":"M2U3","w":820,"h":462,"alt":"People using devices together at home.","cap":"Different people use devices in different ways. This scene shows that an interface that suits one user, such as a child or a grandparent, may not suit another, so designers must consider who will use it.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"The car dashboard: deducing HCI points","src":"i_pDOM_D1GEwk.jpg","pack":"M2U3","w":820,"h":547,"alt":"The dashboard and steering wheel inside a car.","cap":"A car dashboard packs dials, buttons and screens into one small space. Drivers must read it at a glance, so it is a good place to deduce which HCI features and devices are in use.","by":"Jonas Leupe","title":"Real world:"},{"screen":"Lecture notes: data for decisions and types of HCI","src":"i_-OP6XsPyrmM.jpg","pack":"M2U3","w":820,"h":547,"alt":"An open notebook with handwritten notes and a pen on a desk.","cap":"Handwritten notes are a familiar way of recording key points. Reviewing notes like these helps you recall how data supports decisions and which types of HCI suit different users.","by":"Kelly Sikkema","title":"Real world:"}],"M2U4":[{"screen":"Class slides: IT Professionals, Users and System Performance","src":"i_yZpcIxmkxVE.jpg","pack":"M2U4","w":820,"h":462,"alt":"A person working on a computer motherboard","cap":"A person working on a computer motherboard. IT professionals build, maintain and repair systems so that users can rely on them performing well.","by":"Yuriy Vertikov","title":"Real world:"},{"screen":"Why we evaluate an HCI","src":"i_5QiGvmyJTsc.jpg","pack":"M2U4","w":820,"h":547,"alt":"People gathered around a table reviewing designs on paper and screens.","cap":"A group reviews a design together. Evaluating an HCI means checking, with real users and criteria, whether the interface actually helps people complete their tasks.","by":"UX Indonesia","title":"Real world:"},{"screen":"Principle 1: ease of use","src":"i_BCP6GrzZ9gk.jpg","pack":"M2U4","w":820,"h":545,"alt":"A person using a touchscreen device with a simple layout.","cap":"A person completing a task on a simple touch device. Ease of use means users can reach their goal quickly, with little effort and few mistakes.","by":"Gizem Nikomedi","title":"Real world:"},{"screen":"Principle 2: ease of learning","src":"i_4FwEuaWFxgE.jpg","pack":"M2U4","w":820,"h":506,"alt":"A person learning at a desk with a book and notes.","cap":"Someone learning something new step by step. Ease of learning asks how quickly a first-time user can pick up an interface without long training.","by":"Kelly Sikkema","title":"Real world:"},{"screen":"Principle 3: ease of navigation","src":"i_EIfSEvGdHQk.jpg","pack":"M2U4","w":820,"h":547,"alt":"Directional signs guiding people through a public space.","cap":"Signs help people find their way through a busy place. Ease of navigation works the same way on screen: clear menus and labels tell users where they are and where to go next.","by":"Ichisa Yamachi","title":"Real world:"},{"screen":"Principle 4: alignment","src":"i_F4VHOj76D0o.jpg","pack":"M2U4","w":820,"h":547,"alt":"Rows of windows aligned neatly on a building facade.","cap":"Windows set out in tidy rows and columns. In an interface, alignment of text, images and buttons gives a clean, orderly layout that is easy to scan.","by":"Pierre Chatel-Innocenti","title":"Real world:"},{"screen":"Principle 5: use of colour","src":"i_aHaNA8Qcpa8.jpg","pack":"M2U4","w":820,"h":547,"alt":"Brightly coloured shapes in contrasting colours.","cap":"A bold mix of colours. In HCI, colour should be used with purpose: good contrast improves readability, while too many clashing colours can confuse users.","by":"Drew Beamer","title":"Real world:"},{"screen":"How to carry out an HCI evaluation","src":"i_CCg37osralo.jpg","pack":"M2U4","w":820,"h":547,"alt":"A man standing next to a woman using a laptop","cap":"One person observes while another uses a laptop. Watching real users work with a system is a core part of an HCI evaluation.","by":"Mindfield Biosystems","title":"Real world:"},{"screen":"Evaluating HCI in workplaces","src":"i_0e2eYxBiP6A.jpg","pack":"M2U4","w":820,"h":462,"alt":"Colleagues working at computers in a modern office.","cap":"An office where staff depend on computers all day. Evaluating HCI in a workplace looks at whether the systems help employees work efficiently and comfortably.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Evaluating HCI on devices and the web","src":"i_eId5vdwRdQc.jpg","pack":"M2U4","w":820,"h":547,"alt":"A desk with a laptop, tablet and phone.","cap":"A laptop, tablet and phone side by side. Each device has its own interface, so HCI is evaluated separately for devices and for websites viewed on them.","by":"Jakub Zerdzicki","title":"Real world:"},{"screen":"Roles of users: IT professionals","src":"i_eqd0f78u9nI.jpg","pack":"M2U4","w":820,"h":462,"alt":"Racks of computer equipment in a data room.","cap":"Racks of equipment like this are looked after by IT professionals. Their roles range from managing hardware and networks to supporting users of the systems.","by":"Tyler","title":"Real world:"},{"screen":"What \"IT professional\" means","src":"i_BeVGrXEktIk.jpg","pack":"M2U4","w":820,"h":547,"alt":"A headset resting beside a laptop on a desk.","cap":"A headset and laptop, the everyday tools of many IT workers. An IT professional is someone trained to build, run, secure or support computer systems for others.","by":"Petr Machacek","title":"Real world:"},{"screen":"IT roles (1): data, applications, security, management and advice","src":"i_lRoX0shwjUQ.jpg","pack":"M2U4","w":820,"h":569,"alt":"A wall of small wooden drawers used for filing records.","cap":"Drawers of filed records are a physical form of data storage. Managing data, whether on paper or in a database, is one of the key IT roles.","by":"Jan Antonin Kolar","title":"Real world:"},{"screen":"IT roles (2): support, networks, systems and the web","src":"i_mHusyBu4bxM.jpg","pack":"M2U4","w":820,"h":547,"alt":"Two women wearing headsets at a bright office workspace.","cap":"Support staff wearing headsets help users solve problems. This is the IT support role, alongside network, systems and web specialists.","by":"Charanjeet Dhiman","title":"Real world:"},{"screen":"End users: expert and novice","src":"i_8Ec_OEFCkrw.jpg","pack":"M2U4","w":820,"h":462,"alt":"A grandmother and granddaughter taking a selfie with a phone.","cap":"A child and her grandmother share a phone. Users range from expert to novice, and a good interface should work for both the confident and the first-time user.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"User characteristics: age and education","src":"i_UWZNnNQjraI.jpg","pack":"M2U4","w":820,"h":547,"alt":"An older man and woman on a couch looking at a tablet.","cap":"Older adults exploring a tablet together. Age and education affect how people use technology, so interfaces should be clear for users of every age and background.","by":"Centre for Ageing Better","title":"Real world:"},{"screen":"Persons with disabilities and cultural differences","src":"i_6DSItOWspGY.jpg","pack":"M2U4","w":820,"h":547,"alt":"Engineers looking at a computer screen with a prosthetic limb user.","cap":"Engineers work with a user who has a prosthetic limb. Designing for persons with disabilities means involving them so the technology suits their needs.","by":"ThisisEngineering","title":"Real world:"},{"screen":"Adapting interfaces: non-visual, sensors, accessibility features","src":"i_9xxNZCJZ8bA.jpg","pack":"M2U4","w":820,"h":547,"alt":"A computer with a refreshable braille display on a desk.","cap":"A computer with a refreshable braille display lets a blind user read the screen by touch. It is a non-visual adaptation and an accessibility feature.","by":"Elizabeth Woolner","title":"Real world:"},{"screen":"Lecture notes: evaluating HCI, users and adaptive interfaces","src":"i_CKlHKtCJZKk.jpg","pack":"M2U4","w":820,"h":616,"alt":"A fountain pen resting on a lined journal page.","cap":"A pen and journal ready for revision notes. Use them to summarise how HCI is evaluated, who the users are and how interfaces are adapted.","by":"Aaron Burden","title":"Real world:"}],"M2U5":[{"screen":"What is a network, and why build one?","src":"i_fhH2UUype7I.jpg","pack":"M2U5","w":820,"h":527,"alt":"The back of a network patch panel with many cables","cap":"Cables run into a network patch panel. A network links many devices so they can share data, files and resources, which is the reason to build one.","by":"Lee Lawson","title":"Real world:"},{"screen":"Network components and devices","src":"i_eVWWr6nmDf8.jpg","pack":"M2U5","w":820,"h":549,"alt":"Fibre optic cables plugged into a network switch in a rack.","cap":"Fibre cables plugged into a network switch. Switches, cables and similar devices are the components that connect computers and move data on a network.","by":"Kirill Sh","title":"Real world:"},{"screen":"Types of network by area: LAN, MAN and WAN","src":"i_OWxeIPIKwrY.jpg","pack":"M2U5","w":820,"h":544,"alt":"St. Kitts and Nevis seen from above","cap":"St Kitts and Nevis from above. Networks are described by the area they cover, from a single building (LAN) to a town (MAN) or across islands and countries (WAN).","by":"Holger Woizick","title":"Real world:"},{"screen":"The Internet, intranets and extranets","src":"i_nXt5HtLmlgE.jpg","pack":"M2U5","w":820,"h":547,"alt":"A desk globe standing on a table.","cap":"A globe represents the worldwide reach of the Internet. Intranets and extranets use the same technology but limit access to an organisation or its chosen partners.","by":"Kyle Glenn","title":"Real world:"},{"screen":"VPNs and mobile networks","src":"i_oPgukSFxKQw.jpg","pack":"M2U5","w":820,"h":614,"alt":"A tall cell tower standing above trees.","cap":"A cell tower connects mobile phones to the wider network by radio. Mobile networks like this let users stay connected on the move, while VPNs protect data sent over public links.","by":"Steven Van Elk","title":"Real world:"},{"screen":"Network configuration: client-server and peer-to-peer","src":"i_LQ1t-8Ms5PY.jpg","pack":"M2U5","w":820,"h":547,"alt":"Two women sitting beside a table talking.","cap":"Two people talking directly as equals, like a peer-to-peer network where computers share with one another. In client-server, a central server provides services to many clients.","by":"Christina at wocintechchat.com","title":"Real world:"},{"screen":"Network topologies","src":"i_bJmPGAyjH2I.jpg","pack":"M2U5","w":820,"h":547,"alt":"An aerial view of a roundabout in a city.","cap":"A roundabout joins traffic in a circle, much like a ring topology where data passes around a loop. Layout decides how data travels, as with roads.","by":"Ahmad Taufiq Hosni","title":"Real world:"},{"screen":"Comparing topologies","src":"i_7nrsVjvALnA.jpg","pack":"M2U5","w":820,"h":614,"alt":"An aerial view of a large road interchange.","cap":"An interchange with many routes shows how layout affects traffic. Network topologies likewise differ in cost, reliability and what happens when one link fails.","by":"Denys Nevozhai","title":"Real world:"},{"screen":"Transmission media 1: wired (guided) media","src":"i_HAWbM1VDBQI.jpg","pack":"M2U5","w":820,"h":462,"alt":"Plugging in an ethernet cable","cap":"An ethernet cable being plugged in. Wired, or guided, media carry signals along a physical cable such as twisted pair.","by":"2H Media","title":"Real world:"},{"screen":"Transmission media 2: wireless, Wi-Fi and hotspots","src":"i_syCXK9WndqQ.jpg","pack":"M2U5","w":820,"h":544,"alt":"A white and black modem router with indicator lights.","cap":"A router like this sends data by radio waves to nearby devices. Wi-Fi and hotspots are wireless media that need no cables but have limited range.","by":"Misha Feshchak","title":"Real world:"},{"screen":"Network security and firewalls","src":"i_F_KCIRbsxAY.jpg","pack":"M2U5","w":820,"h":547,"alt":"A red padlock fastened on a red metal chain.","cap":"A padlock on a chain is a simple picture of security. Network security uses tools such as firewalls to control what may enter or leave and to keep data safe.","by":"FlyD","title":"Real world:"},{"screen":"Sender, receiver, modulation and bandwidth","src":"i_3YAIvBNlZM4.jpg","pack":"M2U5","w":820,"h":547,"alt":"A large white radio telescope dish under a blue sky.","cap":"A large dish that receives radio signals. It shows the receiver end of communication, where signals sent through a medium must be picked up, and why bandwidth matters.","by":"Stephan Widua","title":"Real world:"},{"screen":"Communication modes: simplex, half duplex and duplex","src":"i_IsnKoKuBvV0.jpg","pack":"M2U5","w":820,"h":462,"alt":"Two men smiling and talking outdoors, one holding a radio.","cap":"Two-way radios let people talk in turn but not at the same time. That is half duplex, unlike simplex (one direction only) or full duplex (both at once, like a phone call).","by":"saad ali","title":"Real world:"},{"screen":"Telecommuting, teleconferencing and videoconferencing","src":"i_eTgMFFzroGc.jpg","pack":"M2U5","w":820,"h":547,"alt":"A laptop showing a video call beside a houseplant.","cap":"A video call from a home desk. Telecommuting, teleconferencing and videoconferencing let people work and meet from different places over a network.","by":"Compagnons","title":"Real world:"},{"screen":"Lecture notes: network components, types and communication","src":"i_1ixT36dfuSQ.jpg","pack":"M2U5","w":820,"h":519,"alt":"A white notebook with a pen on top, on a grey desk.","cap":"A notebook and pen, ready for revision. Use it to summarise the network components, the types of network and the modes of communication.","by":"Diana Polekhina","title":"Real world:"}],"M2U6":[{"screen":"Why networks need standards","src":"i_Annl9CjEaEs.jpg","pack":"M2U6","w":820,"h":546,"alt":"Shipping containers stacked high at a port.","cap":"Shipping containers share one standard size, so they fit any ship, crane or lorry. Network standards do the same for devices from different makers.","by":"Ali Mkumbwa","title":"Real world:"},{"screen":"The OSI model at a glance","src":"i_GqmPjmfpmxo.jpg","pack":"M2U6","w":820,"h":548,"alt":"A three-tiered white cake decorated with flowers.","cap":"A tiered cake is built in layers, each resting on the one below. The OSI model likewise stacks a network task into layers, each with its own job.","by":"Fotografo Samuel Cruz","title":"Real world:"},{"screen":"OSI Layers 7, 6 and 5: the upper layers","src":"i_5QgIuuBxKwM.jpg","pack":"M2U6","w":820,"h":547,"alt":"A person gesturing while talking in a meeting with a laptop.","cap":"People communicating at the top of the stack. The upper OSI layers deal with what the user sees and uses, such as applications, data format and sessions.","by":"Headway","title":"Real world:"},{"screen":"OSI Layers 4 to 1: the lower layers","src":"i_INNsF0Zz_kQ.jpg","pack":"M2U6","w":820,"h":522,"alt":"Blue light passing along fibre optic cables in the dark.","cap":"Light travelling along fibre optic strands. The lower OSI layers move raw bits and frames over cables like these, handling transport, routing and physical transmission.","by":"Compare Fibre","title":"Real world:"},{"screen":"The TCP/IP model","src":"i_Y_cazJRS7AM.jpg","pack":"M2U6","w":820,"h":544,"alt":"Five red post boxes beneath a post office sign.","cap":"Post boxes start a delivery that depends on addresses and agreed steps. In TCP/IP, data is split, addressed and routed to its destination in a similar way.","by":"T","title":"Real world:"},{"screen":"Key protocols you must know","src":"i_srO-NYTfRz8.jpg","pack":"M2U6","w":820,"h":547,"alt":"A cluster of colourful road signs on a road.","cap":"Road signs are rules every driver agrees to follow. Protocols such as HTTP, FTP and SMTP are agreed rules that let devices understand one another.","by":"Nick Fewings","title":"Real world:"},{"screen":"OSI versus TCP/IP, and encapsulation","src":"i_5T5zmIqs0AM.jpg","pack":"M2U6","w":820,"h":547,"alt":"Stacks of shipping containers at a port container terminal.","cap":"Containers are packed, labelled and stacked in layers before shipping. Encapsulation works the same way: each network layer wraps the data in its own header before passing it down, and each layer unwraps it at the other end.","by":"taro ohtani","title":"Real world:"},{"screen":"Network diagrams and standard shapes","src":"i_HtBlQdxfG9k.jpg","pack":"M2U6","w":820,"h":462,"alt":"An architect drawing a plan by hand with a pencil and ruler.","cap":"Architects draw plans using agreed symbols so that anyone can read them. Network diagrams use standard shapes in the same way, so a router, switch or server means the same thing to every reader.","by":"Daniel McCullough","title":"Real world:"},{"screen":"Routers, switches, hubs and Ethernet cables","src":"i_vE5AKQRUs7c.jpg","pack":"M2U6","w":820,"h":547,"alt":"A network switch with several Ethernet cables plugged into its ports.","cap":"A real switch with Ethernet cables in its ports. Switches and hubs connect many devices in a LAN, and the cables carry the data between them.","by":"User_Pascal","title":"Real world:"},{"screen":"Designing a labelled star network","src":"i_T-IN5o3kxyA.jpg","pack":"M2U6","w":820,"h":429,"alt":"Many cables running into a rack-mounted network switch.","cap":"Every cable runs from its own device to a central switch. This is the star layout you draw in a labelled network diagram, with the switch at the centre.","by":"Lightsaber Collection","title":"Real world:"},{"screen":"Firewalls and wired security","src":"i_rhaS97NhnHg.jpg","pack":"M2U6","w":820,"h":547,"alt":"A solid brick wall.","cap":"A wall stops unwanted things getting through and lets in only what you build a door for. A firewall does this for a network, filtering what may pass between the inside and the outside.","by":"Waldemar Brandt","title":"Real world:"},{"screen":"Wireless security: SSID, keys and router passwords","src":"i_43ak6tfF4Ss.jpg","pack":"M2U6","w":820,"h":547,"alt":"A wireless router with two antennas.","cap":"A wireless router broadcasts a signal that anyone nearby can pick up. This is why its SSID, network key and router password need to be set carefully.","by":"dlxmedia.hu","title":"Real world:"},{"screen":"MAC filtering, WPA2, WPA3 and AES","src":"i_q2Zk10NBnsA.jpg","pack":"M2U6","w":820,"h":547,"alt":"A padlock fastened on a blue door.","cap":"A padlock lets in only people who hold the right key. Wireless security works in a similar way, with WPA2 or WPA3 encryption and MAC filtering acting as locks on who may join the network.","by":"Jornada Produtora","title":"Real world:"},{"screen":"Worked example: designing a network step by step","src":"i_sDRKjiDHk3M.jpg","pack":"M2U6","w":820,"h":547,"alt":"Two women standing at a whiteboard planning with notes.","cap":"Two colleagues plan at a whiteboard before building anything. Designing a network step by step starts the same way: list the needs, then sketch the layout before buying any equipment.","by":"Walls.io","title":"Real world:"},{"screen":"Lecture notes: networking standards and network design","src":"i_PSpf_XgOM5w.jpg","pack":"M2U6","w":820,"h":547,"alt":"A bunch of blue network cables connected together","cap":"Blue network cables connected in an organised bundle. Standards ensure equipment from different makers connects properly, and good network design plans cabling like this.","by":"Scott Rodgerson","title":"Real world:"}],"M2U7":[{"screen":"Class slides: IT Professionals, Users and System Performance","src":"i_zBLtU0zbJcU.jpg","pack":"M2U7","w":820,"h":547,"alt":"A broadcast engineer working at equipment in a studio.","cap":"A technical professional keeping complex equipment running for the people who use it. IT professionals do the same for users, and the system's performance depends on both.","by":"ThisisEngineering","title":"Real world:"},{"screen":"From network design to working network","src":"i_oZgzVU_B3sE.jpg","pack":"M2U7","w":820,"h":547,"alt":"A wireless access point mounted near a network switch.","cap":"A switch and access point installed together. A design on paper becomes a working network when real devices like these are fitted, cabled and configured.","by":"User_Pascal","title":"Real world:"},{"screen":"Topologies: bus, ring and star","src":"i_SwVkmowt7qA.jpg","pack":"M2U7","w":820,"h":462,"alt":"A network switch with cables plugged in","cap":"A network switch with cables plugged into it. In a star topology each device connects to a central switch like this.","by":"Jonathan","title":"Real world:"},{"screen":"Devices and cables: routers, hubs, Ethernet, LAN and WAN","src":"i_uWaRsN-CqY0.jpg","pack":"M2U7","w":820,"h":630,"alt":"A blue LAN cable plugged into a router","cap":"A blue LAN cable plugged into a router. Ethernet cables connect devices to routers, which link a local network to other networks.","by":"Franck V.","title":"Real world:"},{"screen":"Configuring the router step by step","src":"i_LR_wX_klOPM.jpg","pack":"M2U7","w":820,"h":536,"alt":"A wireless router with cables","cap":"A router on a desk with its cables connected. Configuring it step by step sets up how the devices on a network connect and communicate.","by":"Stephen Phillips","title":"Real world:"},{"screen":"Wireless security: WPA2, WPA3, AES, network key and MAC filtering","src":"i_7weXfu_XTSw.jpg","pack":"M2U7","w":820,"h":547,"alt":"A person working on a laptop at a cafe table with a coffee.","cap":"Anyone in a public place can try to join a wireless network. WPA2 or WPA3 with AES, a strong network key and MAC filtering help make sure only the right devices connect.","by":"Blake Wisz","title":"Real world:"},{"screen":"Wired security and firewalls","src":"i_tEP6TI8pXW4.jpg","pack":"M2U7","w":820,"h":545,"alt":"A metal door with a lock.","cap":"A locked door controls who can reach what is behind it. Wired network security does the same job, with firewalls and physical controls limiting who can reach the network.","by":"David Trinks","title":"Real world:"},{"screen":"Troubleshooting: start with the physical layer","src":"i_-xITpL_gncA.jpg","pack":"M2U7","w":820,"h":548,"alt":"A network cable tester with an Ethernet cable plugged in.","cap":"A cable tester checks that a network cable is connected and working. Troubleshooting starts at the physical layer: check cables and connections before looking at settings.","by":"Gavin Allanwood","title":"Real world:"},{"screen":"IP address, gateway and DNS: reading ipconfig","src":"i_YMMuClvvvWI.jpg","pack":"M2U7","w":820,"h":547,"alt":"The number 15 on the front of a house.","cap":"A house number lets the post find the right home. An IP address does the same for a device, and the default gateway is the way out of the street to other networks.","by":"Waldemar Brandt","title":"Real world:"},{"screen":"Testing the path with ping","src":"i_Lo5TTZPj5SE.jpg","pack":"M2U7","w":820,"h":547,"alt":"A walkie-talkie lying on a car seat.","cap":"A walkie-talkie user sends a call and waits for a reply to prove the other side can hear. Ping works like this, sending a small message to another device and timing the answer.","by":"Tuan Nguyen","title":"Real world:"},{"screen":"nslookup and the speed test","src":"i_Q77Ocr7p8cM.jpg","pack":"M2U7","w":820,"h":547,"alt":"A printed directory listing names.","cap":"A directory turns a name into the details needed to make contact. DNS does this on the internet, and nslookup asks it for the address that belongs to a name.","by":"luke lasenby","title":"Real world:"},{"screen":"Firewall configurations and a full troubleshooting sequence","src":"i_PkHf7BUWbtk.jpg","pack":"M2U7","w":820,"h":615,"alt":"An electrician testing equipment with a multimeter.","cap":"A technician measures step by step to find a fault instead of guessing. A troubleshooting sequence does this for a network, testing one layer at a time, including firewall settings.","by":"Toolmash Expo","title":"Real world:"},{"screen":"System performance: the whole system, speed and efficiency","src":"i_J30aQDLRb_o.jpg","pack":"M2U7","w":820,"h":547,"alt":"An orchestra and choir performing together on a stage.","cap":"An orchestra sounds good only when every section works together. System performance is the same, since hardware, software, network and user all affect the speed and efficiency of the whole.","by":"Robert Katzki","title":"Real world:"},{"screen":"Comparing components: speed, efficiency and portability","src":"i_eNIAipH_Bcs.jpg","pack":"M2U7","w":820,"h":691,"alt":"A backpack, laptop, headphones, smartphone and tripod laid out together.","cap":"A laptop, phone and accessories that fit in one bag. Portability is how easily a device can be carried, and it is weighed against speed and efficiency when comparing components.","by":"Dean Pugh","title":"Real world:"},{"screen":"Comparing components: maintainability, storage and transmission","src":"i_DQBHliTwIaU.jpg","pack":"M2U7","w":820,"h":547,"alt":"A processor being fitted into a computer motherboard.","cap":"A processor being installed in a motherboard. Parts that can be reached and swapped easily make a system easier to maintain, upgrade and repair.","by":"JESHOOTS.COM","title":"Real world:"},{"screen":"Performance trade-offs: portability and maintainability","src":"i_qzS0Xso98L0.jpg","pack":"M2U7","w":820,"h":547,"alt":"An open laptop with its internal components exposed on a black mat.","cap":"An opened laptop shows how hard it can be to reach its parts. Sealed designs are slim and portable but harder to maintain, which is the trade-off this screen describes.","by":"Ritupon Baishya","title":"Real world:"},{"screen":"Performance trade-offs: storage and transmission","src":"i_raNIrcd39jY.jpg","pack":"M2U7","w":820,"h":547,"alt":"A hard disk drive.","cap":"A hard disk drive stores data on spinning platters. Storage devices differ in capacity and speed, which is why storage and transmission are traded off when choosing components.","by":"Heliberto Arias","title":"Real world:"},{"screen":"Lecture notes: configuring, troubleshooting and comparing components","src":"i_h6gCRTCxM7o.jpg","pack":"M2U7","w":820,"h":547,"alt":"Two colleagues in a meeting discussing work.","cap":"Colleagues reviewing a problem together. Comparing configuring, troubleshooting and component choices is often done as a team discussion, with each decision weighed against others.","by":"ThisisEngineering","title":"Real world:"},{"screen":"Brain Challenge: how do hardware, software, network and user connect?","src":"i_A-b2nPSSK6E.jpg","pack":"M2U7","w":820,"h":547,"alt":"A technician inspecting server racks with a handheld diagnostic tool.","cap":"A technician checks servers and cables that connect hardware, software, network and user. Each part depends on the others, so a fault in one affects the whole system.","by":"Valentin Lacoste","title":"Real world:"}],"M2U8":[{"screen":"Class slides: Access control","src":"i_8FxJi5wuwKc.jpg","pack":"M2U8","w":820,"h":532,"alt":"A security guard standing on a grey floor.","cap":"A security guard checks who may enter a building. Access control works the same way for computers, deciding who is allowed to use which resources.","by":"Collin","title":"Real world:"},{"screen":"Data security and security mechanisms","src":"i_1AucbckEJWk.jpg","pack":"M2U8","w":820,"h":547,"alt":"A large steel vault door.","cap":"A vault protects valuables behind a strong door that opens only for authorised people. Security mechanisms protect data in the same way, with several layers between the data and anyone unauthorised.","by":"Alex Duffy","title":"Real world:"},{"screen":"What is access control?","src":"i_kfqmF_mmTbE.jpg","pack":"M2U8","w":820,"h":547,"alt":"A weathered metal keypad with numbered buttons on a door frame.","cap":"A keypad on a door allows entry only to people who know the code. This is a simple example of access control, where a system decides who may get in.","by":"R. G","title":"Real world:"},{"screen":"The four parts and two phases of access control","src":"i_4JYV3_qJLUs.jpg","pack":"M2U8","w":820,"h":547,"alt":"Turnstiles at an entrance.","cap":"Turnstiles let one person through at a time after they are checked. Access control has the same flow: identify the user, check their rights, then allow or deny entry.","by":"Jerry Wei","title":"Real world:"},{"screen":"Physical versus logical access control","src":"i_cX8kNl8X0Ys.jpg","pack":"M2U8","w":820,"h":547,"alt":"A padlock and keys resting on a computer keyboard.","cap":"A padlock and keys on a keyboard bring both sides together. Physical controls such as locks protect rooms and equipment, while logical controls such as passwords protect the data on the computer.","by":"Sasun Bughdaryan","title":"Real world:"},{"screen":"Who controls access, and identifying the user","src":"i_e1RI3wRelqM.jpg","pack":"M2U8","w":820,"h":547,"alt":"A passport control sign in an airport.","cap":"At passport control an officer checks a document to confirm who you are. Identifying the user comes first in access control, before the system decides what that person may do.","by":"Daniel Schludi","title":"Real world:"},{"screen":"Physical access control measures and devices","src":"i_oQD9uq4Rd4I.jpg","pack":"M2U8","w":820,"h":547,"alt":"Two security cameras mounted on a pole against a blue sky.","cap":"Security cameras are physical access control devices. They watch a place and record who goes where, which deters misuse and helps investigate when something goes wrong.","by":"Michał Jakubowski","title":"Real world:"},{"screen":"Swipe cards and key cards","src":"i_36K2PZYNfcM.jpg","pack":"M2U8","w":820,"h":547,"alt":"A card reader by a door beside a concrete staircase.","cap":"A card reader beside a door opens it only when a valid card is swiped or tapped. Swipe cards and key cards store an identity that the system checks.","by":"Jakub Żerdzicki","title":"Real world:"},{"screen":"Portable-key systems","src":"i_PxiAc1aElFQ.jpg","pack":"M2U8","w":820,"h":462,"alt":"A set of keys lying on a wooden table.","cap":"Keys are portable and work for anyone who holds them, like portable-key systems for computers. If one is lost or copied, someone else gains access, so each key must be managed carefully.","by":"Filip Szalbot","title":"Real world:"},{"screen":"Biometrics","src":"i_lBrJGvBaLlo.jpg","pack":"M2U8","w":820,"h":547,"alt":"A fingerprint reader on a laptop keyboard.","cap":"A fingerprint reader built into a laptop identifies the user by a body feature. This is an everyday example of biometrics, where the user needs no card or password.","by":"Bram Van Oost","title":"Real world:"},{"screen":"Logical access control measures","src":"i_-5XPUpAdcdw.jpg","pack":"M2U8","w":820,"h":548,"alt":"A woman in front of a computer monitor in an office.","cap":"A user at an office computer must prove who they are before using it. Logical access controls such as passwords and user accounts decide who can open files and software.","by":"Proxyclick Visitor Management System","title":"Real world:"},{"screen":"Passwords and effective passwords","src":"i_eNxYF6cexYU.jpg","pack":"M2U8","w":820,"h":615,"alt":"A close-up of a metal keypad with numbered buttons.","cap":"A numeric keypad shows a secret code in everyday use. An effective password is also a secret that should be long, mixed and hard for others to guess.","by":"rc.xyz NFT gallery","title":"Real world:"},{"screen":"Managing passwords well","src":"i_IZj7vckPGiw.jpg","pack":"M2U8","w":820,"h":547,"alt":"An open notebook with lined pages and a pen above it.","cap":"People often write passwords down in a notebook. If you do, keep it locked away and never next to the computer, and use a different password for each account.","by":"engin akyurt","title":"Real world:"},{"screen":"Password lifespan, lockout and passphrases","src":"i_J4eTN9GqhzI.jpg","pack":"M2U8","w":820,"h":547,"alt":"A silver and black combination lock.","cap":"A combination lock opens only with the right sequence. Long passphrases and a limit on wrong attempts, followed by lockout, make guessing a secret far harder.","by":"Nicolas HIPPERT","title":"Real world:"},{"screen":"Authentication","src":"i_RPlbDSlkoHI.jpg","pack":"M2U8","w":820,"h":546,"alt":"A black electronic banking card reader with a numeric keypad on a red surface","cap":"A card reader with a numeric keypad. Entering a PIN is a form of authentication, proving you are who you claim to be before access is allowed.","by":"Artur Uber","title":"Real world:"},{"screen":"Encryption","src":"i_Lexcm-6FHRU.jpg","pack":"M2U8","w":820,"h":547,"alt":"A silver padlock fastened to a metal fixture.","cap":"A padlock keeps a door shut unless you hold the key. Encryption works in the same way, locking data so that only someone with the correct key can read it.","by":"Zaqy Al Fattah","title":"Real world:"},{"screen":"Data integrity","src":"i_ZH4FUYiaczY.jpg","pack":"M2U8","w":820,"h":547,"alt":"A person signing a paper contract with a pen at a desk.","cap":"A signature shows that a document is genuine and has not been swapped. Data integrity is the same assurance for digital data: it is accurate, complete and has not been altered without authority.","by":"Dimitri Karastelev","title":"Real world:"},{"screen":"Data corruption","src":"i_7GPnPHRksDE.jpg","pack":"M2U8","w":820,"h":547,"alt":"A lit candle burning in a dark room.","cap":"A candle flame is easily disturbed and the light can fade without warning. Data can likewise be damaged or lost through faults or interference, which is data corruption.","by":"siddharth kushwaha","title":"Real world:"},{"screen":"Why access control matters","src":"i__we0BQQewBo.jpg","pack":"M2U8","w":820,"h":548,"alt":"A steel gate closed and secured with a padlock.","cap":"A locked gate lets approved people in and keeps everyone else out. Access control does this for computer systems, protecting data and resources from unauthorised users.","by":"Masaaki Komori","title":"Real world:"},{"screen":"Comparing security mechanisms","src":"i_Go4Vw_6gq_k.jpg","pack":"M2U8","w":820,"h":546,"alt":"A contactless card reader on a station ticket gate.","cap":"A gate that opens only for a valid card is one security mechanism among many. Passwords, cards and biometrics each trade cost, convenience and strength differently, so they are compared.","by":"Reuben Hu","title":"Real world:"},{"screen":"Lecture notes: security mechanisms and security terms","src":"i_CqSpoJs2ehg.jpg","pack":"M2U8","w":820,"h":547,"alt":"A facial recognition device mounted for entry control.","cap":"A facial recognition device identifies people by their physical features, an example of biometric authentication. It is one of the security mechanisms summarised in these lecture notes.","by":"Maxim Tolchinskiy","title":"Real world:"}],"M2U9":[{"screen":"Class slides: The World Wide Web and Internet standards","src":"i_nomAp6_KVXU.jpg","pack":"M2U9","w":820,"h":547,"alt":"A world map with pins marking locations.","cap":"A world map with pins suggests how the Web links places and people across the globe. Internet standards let computers everywhere communicate with one another.","by":"Leandro Barreto","title":"Real world:"},{"screen":"The Internet and the World Wide Web","src":"i_SsAFdirwkXc.jpg","pack":"M2U9","w":820,"h":546,"alt":"Telecommunication towers on Winter Hill, Bolton","cap":"Telecommunication towers on Winter Hill, Bolton. The Internet depends on physical infrastructure like this, while the World Wide Web is the collection of pages that runs over it.","by":"David Arrowsmith","title":"Real world:"},{"screen":"Where it all began: from defence network to CERN","src":"i_9ah3OEzPSXI.jpg","pack":"M2U9","w":820,"h":549,"alt":"A Macintosh Plus computer","cap":"A Macintosh Plus, a personal computer from the early days of computing. The Internet and Web grew from early networks to CERN, long before such machines became museum pieces.","by":"Tomas Martinez","title":"Real world:"},{"screen":"Hypertext and hyperlinks","src":"i_rhCZIm9pp54.jpg","pack":"M2U9","w":820,"h":615,"alt":"An early Macintosh computer manual lying on a table.","cap":"Early computer manuals show how documents once had to be read in a fixed order. Hypertext lets readers follow hyperlinks from one document straight to another.","by":"Brett Jordan","title":"Real world:"},{"screen":"Browsers, hyperlinks, home pages, web pages and web sites","src":"i_A9Msi-vUNKg.jpg","pack":"M2U9","w":820,"h":547,"alt":"A person using a laptop computer on their lap.","cap":"A person browsing on a laptop is using a web browser to open web pages. Pages are linked by hyperlinks and grouped together as a web site starting from a home page.","by":"Andrew Neel","title":"Real world:"},{"screen":"Web pages: static or dynamic, and the home page","src":"i_xzzgY__zX8A.jpg","pack":"M2U9","w":820,"h":547,"alt":"Hand-drawn website layouts on paper","cap":"Hand-drawn website layouts. Designers sketch the home page and other pages first, deciding what is fixed (static) and what will change (dynamic).","by":"Hal Gatewood","title":"Real world:"},{"screen":"HTTP and the URL","src":"i_9CR19q291ac.jpg","pack":"M2U9","w":820,"h":462,"alt":"A waiter taking an order from customers seated at a cafe.","cap":"Ordering at a cafe is a request followed by a response, just like HTTP. The browser asks for a page and the server replies with it.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Web servers, web browsers and the URL","src":"i_FvpVY7TpwNY.jpg","pack":"M2U9","w":820,"h":615,"alt":"A website wireframe displayed on a laptop","cap":"A website layout open on a laptop. A browser requests a page by its URL from a web server, then displays it like this.","by":"Amper","title":"Real world:"},{"screen":"Protocols in a URL","src":"i__XeQ8XEWb4Q.jpg","pack":"M2U9","w":820,"h":547,"alt":"Two people shaking hands in front of an open laptop.","cap":"A handshake shows two parties agreeing on how to deal with each other. A protocol such as http or https in a URL sets the agreed rules for the exchange.","by":"Radission US","title":"Real world:"},{"screen":"HTML: markup, tags, the root element and plug-ins","src":"i_Plso5cHu9w0.jpg","pack":"M2U9","w":820,"h":547,"alt":"A red felt-tip pen resting on a blank notebook.","cap":"Marking up a page with a pen adds instructions around the text without changing the words. HTML markup works in the same way, with tags telling the browser how to display content.","by":"Kelly Sikkema","title":"Real world:"},{"screen":"HTML and XML","src":"i_fb7yNPbT0l8.jpg","pack":"M2U9","w":820,"h":547,"alt":"A row of six colourful mailboxes.","cap":"Each mailbox has its own place and holds a different kind of content. XML similarly lets authors define their own labelled tags to describe and store data, while HTML tags are fixed.","by":"Mathyas Kurmann","title":"Real world:"},{"screen":"Domain names, IP addresses and domain name resolution","src":"i_4SECq2nWI1c.jpg","pack":"M2U9","w":820,"h":615,"alt":"A wall of numbered mailboxes.","cap":"Numbered mailboxes identify where mail should go, as an IP address identifies a computer. Domain name resolution translates a readable name into the number.","by":"Tim Wildsmith","title":"Real world:"},{"screen":"IP addresses and domain names in detail","src":"i_EcilfXQRgLw.jpg","pack":"M2U9","w":820,"h":547,"alt":"A mailbox marked with the number four.","cap":"A house number lets the postal service find a building, just as an IP address lets data find one device. The domain name is the easier label that people remember.","by":"Jackie Alexander","title":"Real world:"},{"screen":"TCP/IP: the Internet Protocol Suite","src":"i_qVpGF1mlaM8.jpg","pack":"M2U9","w":820,"h":547,"alt":"A conveyor belt moving packages inside a large warehouse.","cap":"Parcels moving through a warehouse are sorted and sent onward, as data travels in packets. TCP/IP defines how packets are addressed, routed and reassembled at their destination.","by":"Alberto Rodríguez","title":"Real world:"},{"screen":"HTML document structure, elements and attributes","src":"i_Yn8D5B8C-eY.jpg","pack":"M2U9","w":820,"h":552,"alt":"Architectural blueprints with drafting tools on a table.","cap":"A blueprint sets out the structure of a building before it is made. An HTML document likewise has a defined structure of elements and attributes that the browser follows.","by":"Lucas Kepner","title":"Real world:"},{"screen":"Headers, paragraphs, text formatting and comments","src":"i_4UGmm3WRUoQ.jpg","pack":"M2U9","w":820,"h":615,"alt":"A hand-drawn wireframe on paper","cap":"A hand-drawn page wireframe with a heading and blocks of text. HTML headers and paragraphs give a web page this kind of structure.","by":"Compagnons","title":"Real world:"},{"screen":"Inline styling with the style attribute","src":"i_PtabTe6iJ_8.jpg","pack":"M2U9","w":820,"h":548,"alt":"A fan of paper colour swatches.","cap":"Colour swatches help a designer choose exactly how something will look. The style attribute lets you set colour and other appearance details directly on an HTML element.","by":"Mika Baumeister","title":"Real world:"},{"screen":"Lists and images","src":"i_pcpsVsyFp_s.jpg","pack":"M2U9","w":820,"h":547,"alt":"A notepad with a pen resting on it.","cap":"A handwritten list shows items arranged one under another. HTML offers ordered and unordered lists, and images can be added to a page alongside them.","by":"Thomas Bormans","title":"Real world:"},{"screen":"Tables","src":"i_aeQ-M0bztJE.jpg","pack":"M2U9","w":820,"h":616,"alt":"A ferry departures board listing times and destinations.","cap":"A departures board organises information in rows and columns. An HTML table does the same, using rows, cells and headings.","by":"Vinicius Brasil","title":"Real world:"},{"screen":"Forms","src":"i_zQCDJZLS-Ms.jpg","pack":"M2U9","w":820,"h":547,"alt":"A clipboard with a pencil and pen on a wooden surface.","cap":"A clipboard holds a paper form to be filled in. HTML forms collect information from users in a similar way, through fields that are then submitted.","by":"Kelly Sikkema","title":"Real world:"},{"screen":"Hyperlinks","src":"i_sOdzJEsGDLA.jpg","pack":"M2U9","w":820,"h":547,"alt":"A signpost with several arrows pointing in different directions.","cap":"A signpost points travellers towards different destinations. Hyperlinks do this on the Web, taking readers from one page to another.","by":"Ian Ward","title":"Real world:"},{"screen":"Lecture notes: The Internet, the Web and HTML","src":"i_5bYxXawHOQg.jpg","pack":"M2U9","w":820,"h":547,"alt":"A brown fountain pen lying on an open notebook.","cap":"Taking notes helps you consolidate what you have learned. These lecture notes bring together the Internet, the Web and HTML.","by":"David Travis","title":"Real world:"}],"M3U1":[{"screen":"What is a problem?","src":"i_cWMhxNmQVq0.jpg","pack":"M3U1","w":820,"h":552,"alt":"A puzzle with one piece missing.","cap":"A puzzle with a missing piece shows a gap between how things are and how they should be. That gap is what we call a problem.","by":"Tanja Tepavac","title":"Real world:"},{"screen":"Problem-solving as a process [SO 3.1]","src":"i_zLIUdGeKxv0.jpg","pack":"M3U1","w":820,"h":547,"alt":"A pale staircase with railings.","cap":"Climbing a staircase happens one step at a time, in order. Problem-solving is a process in which each step builds on the one before.","by":"Alessia Cocconi","title":"Real world:"},{"screen":"The six stages at a glance [SO 3.2]","src":"i_Z61MuLuFQDQ.jpg","pack":"M3U1","w":820,"h":634,"alt":"White stairs with black railings.","cap":"A staircase with a clear number of steps resembles the six stages of problem-solving. Each stage leads to the next, from defining the problem to evaluating the result.","by":"Ricardo Gomez Angel","title":"Real world:"},{"screen":"Stage 1: Define the problem","src":"i_gt8AFN5ehjg.jpg","pack":"M3U1","w":820,"h":545,"alt":"A plant with green leaves.","cap":"Before fixing anything you must say clearly what is wrong. Defining a problem might begin with observing something, such as a plant that is not healthy.","by":"Tom Jur","title":"Real world:"},{"screen":"Writing problem statements","src":"i_Ax8IA8GAjVg.jpg","pack":"M3U1","w":820,"h":556,"alt":"A person writing on white paper.","cap":"Writing a problem down forces you to be precise. A good problem statement says clearly what is wrong, for whom, and what outcome is needed.","by":"Brands&People","title":"Real world:"},{"screen":"Stage 2: Analyse the problem","src":"i_AteFNIFVGdo.jpg","pack":"M3U1","w":820,"h":462,"alt":"A person holding a black magnifying glass.","cap":"A magnifying glass lets you examine details closely. Analysing a problem means investigating its causes, effects and requirements in the same careful way.","by":"Nwar Igbariah","title":"Real world:"},{"screen":"Stage 3: Identify and evaluate possible solutions","src":"i_ETRPjvb0KM0.jpg","pack":"M3U1","w":820,"h":547,"alt":"Colourful sticky notes pinned to a board.","cap":"Sticky notes on a board are a common way to brainstorm many ideas. In this stage you list possible solutions and evaluate the strengths and weaknesses of each.","by":"Patrick Perkins","title":"Real world:"},{"screen":"Stage 4: Select and justify the optimal solution","src":"i_C7B-ExXpOIE.jpg","pack":"M3U1","w":820,"h":547,"alt":"A road sign silhouette against the sky.","cap":"A road sign at a junction means picking one route. Selecting the optimal solution means choosing the best option and justifying why it beats the others.","by":"Javier Allegue Barros","title":"Real world:"},{"screen":"Stage 5: Implement","src":"i_X1P1_EDNnok.jpg","pack":"M3U1","w":820,"h":547,"alt":"A construction worker in a hard hat on a building frame.","cap":"Construction turns plans into something real. Implementation puts the chosen solution into practice by following the plan.","by":"Josh Olalde","title":"Real world:"},{"screen":"Stage 6: Evaluate and review","src":"i_1AoGjqdyDLU.jpg","pack":"M3U1","w":820,"h":548,"alt":"A soybean farmer tending crops","cap":"A farmer tending crops and checking how they are growing. Evaluating and reviewing a solution is similar: check the results, then decide what to improve.","by":"Richard Nyoni","title":"Real world:"},{"screen":"Worked case: Carenage Water Taxi","src":"i_eLWWiDeVFKk.jpg","pack":"M3U1","w":820,"h":605,"alt":"A ferry on the water.","cap":"A ferry is a transport service with schedules, passengers and capacity to manage. The Carenage Water Taxi case applies the six problem-solving stages to such a service.","by":"Adam Marikar","title":"Real world:"},{"screen":"Linking the stages to Paper 03","src":"i_8gAbl776pc0.jpg","pack":"M3U1","w":820,"h":462,"alt":"Students gathered around a laptop","cap":"Students working together around a laptop. Paper 03 asks you to apply the problem-solving stages to a real situation, much as a group would plan a task.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Exam technique for SO 3.1 and SO 3.2","src":"i_cbEvoHbJnIE.jpg","pack":"M3U1","w":820,"h":547,"alt":"A pencil resting on an answer sheet.","cap":"Good exam technique means reading the question carefully, using the correct terms and linking answers to the scenario. Practising answers on SO 3.1 and SO 3.2 builds that skill.","by":"Nguyen Dang Hoang Nhu","title":"Real world:"},{"screen":"Lecture notes: Problem-solving and its stages","src":"i_erWc6mrOq_I.jpg","pack":"M3U1","w":820,"h":547,"alt":"A mechanic inspecting a car engine","cap":"A mechanic inspecting an engine. Problem-solving follows stages: identify the fault, plan a fix, carry it out, then test and review the result.","by":"Dextar Studio","title":"Real world:"}],"M3U2":[{"screen":"Class slides: The role of information","src":"i_WYd_PkCa1BY.jpg","pack":"M3U2","w":820,"h":547,"alt":"Pages of a business newspaper.","cap":"Newspapers carry information that helps people to make decisions. The role of information is to support decision making by turning facts into something meaningful.","by":"AbsolutVision","title":"Real world:"},{"screen":"Class slides: Evaluating information","src":"i_yx17UuZw1Ck.jpg","pack":"M3U2","w":820,"h":547,"alt":"A black magnifying glass lying on white paper.","cap":"A magnifying glass lets you check detail closely. Evaluating information means checking its accuracy, relevance, timeliness and source before relying on it.","by":"Mediamodifier","title":"Real world:"},{"screen":"Every problem has an information component","src":"i_TmxcAZIhkNw.jpg","pack":"M3U2","w":820,"h":547,"alt":"An agronomist examining crops in a tobacco field.","cap":"A farmer inspects a crop in the field. Every real problem, such as a failing crop, has an information component: someone must gather facts about it before acting.","by":"Siwawut Phoophinyo","title":"Real world:"},{"screen":"A problem is a gap: information supports decisions","src":"i_iLrMmnIL8x4.jpg","pack":"M3U2","w":820,"h":615,"alt":"Stepping stones leading across a river.","cap":"Stepping stones bridge a gap between two banks. A problem is a gap in the same way, and the right information is what lets us decide where to step next.","by":"Lisa Baker","title":"Real world:"},{"screen":"Information for personal problems","src":"i_J4KsphFse-c.jpg","pack":"M3U2","w":820,"h":462,"alt":"An elderly couple reviewing household papers and finances together at a table.","cap":"A couple reviews their household finances. Personal problems like budgeting depend on information such as income, bills and savings, gathered before a decision is made.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"An information problem: the guava jelly exporter","src":"i_xLMUVG1hP_Q.jpg","pack":"M3U2","w":820,"h":615,"alt":"Guavas and mangoes displayed on a market stall.","cap":"Fresh guavas on a market stall. A guava jelly exporter would need information on supply, prices, buyers and regulations, which shows how a business problem is really an information problem.","by":"Ashen Bandaranayake","title":"Real world:"},{"screen":"Information for commercial problems","src":"i_rWMIbqmOxrY.jpg","pack":"M3U2","w":820,"h":615,"alt":"A grocery store aisle with shelves of products.","cap":"A supermarket aisle full of products. Commercial problems such as pricing and stocking rely on information about customers, competitors and costs.","by":"Nathália Rosa","title":"Real world:"},{"screen":"Information for scientific problems","src":"i_SZJoYW4eLHE.jpg","pack":"M3U2","w":820,"h":547,"alt":"A man in a laboratory writing down experiment details.","cap":"A scientist records experiment details in a laboratory. Scientific problems need carefully collected and recorded information so that results can be checked and repeated.","by":"Hush Naidoo Jade Photography","title":"Real world:"},{"screen":"Information for social problems","src":"i_Tf7ysdubEHE.jpg","pack":"M3U2","w":820,"h":547,"alt":"Cars driving along a flooded street during a storm.","cap":"Cars move through a flooded street in a storm. Social problems like flooding need information about weather, roads and people at risk so that communities can respond.","by":"Aldward Castillo","title":"Real world:"},{"screen":"Categorising information: four categories","src":"i_2P1OGyPbiQ4.jpg","pack":"M3U2","w":820,"h":547,"alt":"A person sorting chilli peppers at a market.","cap":"Chilli peppers being sorted at a market. Sorting items into groups is like categorising information into four categories so that it can be used more easily.","by":"Rosa Ferreira","title":"Real world:"},{"screen":"Categories depend on the problem","src":"i_xDNwySMfR5I.jpg","pack":"M3U2","w":820,"h":462,"alt":"A doctor writing in a patient's medical records.","cap":"A doctor records notes in a patient file. The same facts can be sorted differently depending on the problem, so the useful categories change with the situation.","by":"Vitaly Gariev","title":"Real world:"},{"screen":"Why we accept or reject information","src":"i__FilM6g6DEQ.jpg","pack":"M3U2","w":820,"h":547,"alt":"Coffee being poured through a Chemex filter.","cap":"Coffee passes through a filter that keeps some material back. We filter information in the same way, accepting what is useful and reliable and rejecting what is not.","by":"Thomas Martinsen","title":"Real world:"},{"screen":"Common sense first, then the validity questions","src":"i__Zua2hyvTBk.jpg","pack":"M3U2","w":820,"h":548,"alt":"A man sitting on a bench reading a newspaper.","cap":"A man reads a newspaper. Before trusting what we read, common sense comes first, then the more formal validity questions about the source.","by":"Roman Kraft","title":"Real world:"},{"screen":"Criterion 1: bias","src":"i_yCdPU73kGSc.jpg","pack":"M3U2","w":820,"h":547,"alt":"A statue of Lady Justice holding balanced scales.","cap":"Lady Justice holds scales to weigh evidence fairly. Bias is a leaning to one side, and good information should be balanced like the scales.","by":"Tingey Injury Law Firm","title":"Real world:"},{"screen":"Criteria 2 and 3: accuracy and completeness","src":"i_cixohzDpNIo.jpg","pack":"M3U2","w":820,"h":547,"alt":"A tape measure lying on a surface.","cap":"A tape measure gives exact readings. Accuracy means information is correct, and completeness means nothing important has been left out.","by":"Siora Photography","title":"Real world:"},{"screen":"Criteria 4 and 5: currency and cultural context","src":"i_OJWivczp3aY.jpg","pack":"M3U2","w":820,"h":622,"alt":"A calendar with days crossed out","cap":"A calendar with days crossed off shows how quickly time passes. Currency asks how up to date a source is, alongside whether it suits its cultural context.","by":"Adam Tinworth","title":"Real world:"},{"screen":"Criterion 6: refereed and un-refereed sources","src":"i_6NMcUDG37Yc.jpg","pack":"M3U2","w":820,"h":544,"alt":"People in lab coats looking together at a tablet.","cap":"Researchers in lab coats review findings together. Refereed sources are checked by experts before publication, unlike un-refereed ones.","by":"National Cancer Institute","title":"Real world:"},{"screen":"Refereed publications and the level of scholarship","src":"i_JcPr4irSk34.jpg","pack":"M3U2","w":820,"h":548,"alt":"Students studying in the Suzzallo Library at the University of Washington in Seattle.","cap":"Students study in a university library. Refereed publications reach a high level of scholarship because they are reviewed before they appear.","by":"Zoshua Colah","title":"Real world:"},{"screen":"Specificity, relevance and the authority of the author","src":"i_2j0acCTvBWM.jpg","pack":"M3U2","w":820,"h":547,"alt":"Wooden card catalogue drawers with small label holders in a library.","cap":"A library card catalogue stores records in labelled drawers. Finding a card quickly depends on how specific and relevant the label is, much like judging how specific and relevant information is, and who stands behind it.","by":"Ilya Semenov","title":"Real world:"},{"screen":"Familiarity with the literature, accuracy and timeliness","src":"i_eeSdJfLfx1A.jpg","pack":"M3U2","w":820,"h":547,"alt":"A book stall on Portobello Road in London.","cap":"Books for sale at a stall. Checking whether an author knows the literature, and whether the work is accurate and timely, helps you choose reliable sources.","by":"Ed Robertson","title":"Real world:"},{"screen":"Does the research require objectivity?","src":"i_6q1C_XDNR4s.jpg","pack":"M3U2","w":820,"h":547,"alt":"A technician carrying out a test in a laboratory.","cap":"A technician performs a laboratory test. Some research must be objective, meaning results should not depend on the opinions of the person doing the test.","by":"National Cancer Institute","title":"Real world:"},{"screen":"Criterion 7: characteristics of information on the Internet","src":"i_wvlyUYpo_5k.jpg","pack":"M3U2","w":820,"h":548,"alt":"A large pile of folded newspapers stacked together.","cap":"A pile of newspapers shows how much information is available at once. Not all of it is accurate, current or reliable, so online information must be judged against criteria such as accuracy, authority and timeliness.","by":"Greg Bulla","title":"Real world:"},{"screen":"Internet information: who published it, and was it approved?","src":"i_7PMGUqYQpYc.jpg","pack":"M3U2","w":820,"h":547,"alt":"A wooden stamp marked 'checked' on a document.","cap":"A stamp marks a document as checked. On the Internet we ask who published a page and whether anyone approved or reviewed it.","by":"Markus Spiske","title":"Real world:"},{"screen":"Internet information: last updated, and links to and from the page","src":"i_bwOAixLG0uc.jpg","pack":"M3U2","w":820,"h":548,"alt":"A calendar with red push pins marking dates.","cap":"A calendar with pins marking dates. A web page's last-updated date, and the links to and from it, help show how current and well connected it is.","by":"Towfiqu barbhuiya","title":"Real world:"},{"screen":"Applying the criteria: a worked evaluation","src":"i_NbEVXgI5C6U.jpg","pack":"M3U2","w":820,"h":547,"alt":"A technician completing a check sheet next to equipment.","cap":"A technician works through a check sheet beside equipment. Applying the criteria to a source is the same step-by-step check, with a finding for each one.","by":"TECNIC Bioprocess Solutions","title":"Real world:"},{"screen":"Brain Challenge: domains and information","src":"i_Z2pq_4mj6BI.jpg","pack":"M3U2","w":820,"h":547,"alt":"Close-up of an Aedes mosquito.","cap":"This Aedes mosquito is a species that can transmit dengue, Zika and chikungunya. Information about mosquitoes is a domain of knowledge that can be applied to a real health problem.","by":"National Institute of Allergy and Infectious Diseases","title":"Real world:"}],"M3U3":[{"screen":"What is a software development model?","src":"i_m9qMoh-scfE.jpg","pack":"M3U3","w":820,"h":547,"alt":"Architectural drawings and plans spread on a desk.","cap":"Architectural drawings are plans drawn up before building starts. A software development model works the same way, giving a structured plan for the order in which work on a system is carried out.","by":"Sergey Zolkin","title":"Real world:"},{"screen":"The Waterfall model","src":"i_waAAaeC9hns.jpg","pack":"M3U3","w":820,"h":535,"alt":"A waterfall in the Kyoto Garden, Holland Park.","cap":"Water flows down a waterfall in one direction and cannot return. The Waterfall model moves through its stages in the same way, one after another.","by":"Mike Lewis HeadSmart Media","title":"Real world:"},{"screen":"Waterfall: usage, advantages and disadvantages","src":"i_em4mkYiN_54.jpg","pack":"M3U3","w":820,"h":547,"alt":"Cranes working on the construction of a bridge across a river.","cap":"Cranes build a bridge. Large projects with clear, fixed requirements suit Waterfall, though changing the plan late is costly.","by":"Nathan Sack","title":"Real world:"},{"screen":"Evolutionary development (prototyping)","src":"i_Dl7CtzT7Iyw.jpg","pack":"M3U3","w":820,"h":616,"alt":"An unfinished clay portrait sculpture.","cap":"An unfinished clay sculpture that is shaped and reshaped. Evolutionary development works like this, refining a working model in response to feedback.","by":"Elijah Crouch","title":"Real world:"},{"screen":"Prototyping: usage, advantages and disadvantages","src":"i_1hEhb26Bn20.jpg","pack":"M3U3","w":820,"h":522,"alt":"An architectural model in front of blueprints on a wall.","cap":"An architectural model stands in front of blueprints. A prototype lets users see and test an idea early, though it may hide how much work remains.","by":"Declan Sun","title":"Real world:"},{"screen":"Iterative and incremental development","src":"i_i6V6diaf71A.jpg","pack":"M3U3","w":820,"h":547,"alt":"A person applying cement to a brick wall.","cap":"A wall grows one section at a time. Iterative and incremental development builds a system in the same way, adding finished pieces each cycle.","by":"Solømen","title":"Real world:"},{"screen":"Iterative/incremental: usage, advantages and disadvantages","src":"i_oL3cNYKY3yU.jpg","pack":"M3U3","w":820,"h":548,"alt":"A man laying blocks on a wall.","cap":"A man lays blocks to build a wall. Each block is a usable increment, which is why this model delivers working parts early.","by":"Oladipo Adejumo","title":"Real world:"},{"screen":"Agile software development","src":"i_JXyY3jRV9oI.jpg","pack":"M3U3","w":820,"h":544,"alt":"A project planning board with sticky notes arranged in columns.","cap":"A planning board with notes sorted into columns. Agile teams plan and track small pieces of work in short cycles.","by":"Paymo","title":"Real world:"},{"screen":"Agile: usage, advantages and disadvantages","src":"i_H3htK85wwnU.jpg","pack":"M3U3","w":820,"h":547,"alt":"Men rowing together on the Yarra River in Melbourne.","cap":"A rowing crew pulls in time. Agile relies on close teamwork and constant communication, which works best when everyone coordinates.","by":"Mitchell Luo","title":"Real world:"},{"screen":"Comparing the four models","src":"i_Rf9eElW3Qxo.jpg","pack":"M3U3","w":820,"h":531,"alt":"An assortment of carpentry tools laid out together.","cap":"A set of different tools. Each development model is a tool with strengths and weaknesses, so comparing them means asking which suits the job.","by":"Louis Hansel","title":"Real world:"},{"screen":"How to choose a model for a scenario","src":"i_cqH4_fBvVPg.jpg","pack":"M3U3","w":820,"h":547,"alt":"Two signs hanging from a metal pole.","cap":"Two signs on a pole point to different choices. Choosing a model means weighing the scenario and picking the one that fits best.","by":"Sophia Kunkel","title":"Real world:"},{"screen":"Worked examples: choosing and justifying","src":"i_5lNKe_pE3oA.jpg","pack":"M3U3","w":820,"h":547,"alt":"A person writing on a piece of paper.","cap":"Someone writes out their reasoning on paper. Worked examples show how to choose a model and justify the choice with evidence from the scenario.","by":"Billy Albert","title":"Real world:"},{"screen":"Exam technique and common errors","src":"i__urKfD3fUK8.jpg","pack":"M3U3","w":820,"h":547,"alt":"A boy writing on paper at a desk.","cap":"A student writes an answer. Good exam technique means naming the model, linking it to the scenario and avoiding common errors.","by":"April Walker","title":"Real world:"},{"screen":"Lecture notes: software development models","src":"i_F8t2VGnI47I.jpg","pack":"M3U3","w":820,"h":548,"alt":"An empty university lecture hall in Seoul.","cap":"A lecture hall where notes are taken. These lecture notes summarise the main software development models.","by":"Changbok Ko","title":"Real world:"}],"M3U4":[{"screen":"Class slides: The System Development Life Cycle","src":"i_Tv2AtkG_ilM.jpg","pack":"M3U4","w":820,"h":516,"alt":"A woman standing beside a projector screen presenting to an audience.","cap":"A presenter uses a projected screen to take a group through a topic step by step. Class slides do the same job for the System Development Life Cycle, setting out its phases in order.","by":"Van Tay Media","title":"Real world:"},{"screen":"What the SDLC is and why it exists","src":"i_Q-e1-nxrRIc.jpg","pack":"M3U4","w":820,"h":544,"alt":"A young plant sprouting from the ground.","cap":"A young plant sprouts and will grow through stages. A life cycle describes the stages a system passes through, and the SDLC gives that process an order.","by":"Geri Jean","title":"Real world:"},{"screen":"Nine phases and the syllabus six","src":"i_MrbJwbvAkEI.jpg","pack":"M3U4","w":820,"h":547,"alt":"A small seedling growing up through fallen leaves.","cap":"A seedling passes through stages, from sprouting to growth. A system likewise moves through a series of connected phases from its first idea to a working product, which is the idea behind the life cycle.","by":"Wolfgang Hasselmann","title":"Real world:"},{"screen":"Software engineering","src":"i_hoivM01c-vg.jpg","pack":"M3U4","w":820,"h":547,"alt":"A female civil engineer designing weirs on a computer.","cap":"An engineer designs on a computer using planned methods. Software engineering applies the same disciplined approach to building software.","by":"ThisisEngineering","title":"Real world:"},{"screen":"Stage 1: the feasibility study","src":"i_X4VwfPzy_2o.jpg","pack":"M3U4","w":820,"h":547,"alt":"A calculator, pen and banknotes on a desk.","cap":"A calculator, pen and money represent weighing costs against benefits. A feasibility study does this at the start of a project, checking whether a new system is affordable and worthwhile before work begins.","by":"Sasun Bughdaryan","title":"Real world:"},{"screen":"Problem definition, the system proposal and the feasibility report","src":"i_v89zhr0iBFY.jpg","pack":"M3U4","w":820,"h":547,"alt":"Sticky notes arranged as a plan on a glass wall.","cap":"Sticky notes on a glass wall show a team defining a problem and setting out a plan. This mirrors writing a problem definition and a system proposal, then summarising the findings in a feasibility report.","by":"airfocus","title":"Real world:"},{"screen":"Project planning: the project management plan and Gantt chart","src":"i_qWwpHwip31M.jpg","pack":"M3U4","w":820,"h":547,"alt":"A software team planning an app flow on a board with notes.","cap":"A team maps out tasks on a board. A project management plan and Gantt chart do the same job formally, laying out who does what and when.","by":"Alvaro Reyes","title":"Real world:"},{"screen":"Stage 2: analysis and the requirements specification","src":"i_ZlOlRnWk8zU.jpg","pack":"M3U4","w":820,"h":546,"alt":"Two women in a warehouse, one holding a clipboard while they talk.","cap":"An analyst with a clipboard talks to a worker in a real workplace. Analysis means studying how the current system operates before writing the requirements specification.","by":"Centre for Ageing Better","title":"Real world:"},{"screen":"Stage 3: design, diagrams and charts","src":"i_0-ipMJsOIlE.jpg","pack":"M3U4","w":820,"h":462,"alt":"Overhead view of diagrams and charts on paper.","cap":"Designers sketch diagrams and charts before building anything. In the design stage of the life cycle, analysts do the same with tools such as flowcharts and data flow diagrams to show how the system will work.","by":"GUO ZIYU","title":"Real world:"},{"screen":"The design specification: logical design, physical design and prototypes","src":"i_UW4_FYJ_jRc.jpg","pack":"M3U4","w":820,"h":547,"alt":"A small model house resting on an open book.","cap":"A model house shows what a building will look like before it is built. A prototype does this for software, giving users something to try and comment on before the final system is built.","by":"Fernando Andrade","title":"Real world:"},{"screen":"Deliverable: the test plan","src":"i_yKnIbJV0RbY.jpg","pack":"M3U4","w":820,"h":462,"alt":"A hand ticking items on a checklist displayed on a tablet.","cap":"A checklist ticked item by item shows the idea of a test plan. A test plan lists what must be checked, the data to use and the expected results, so each part of the system is verified.","by":"Jakub Zerdzicki","title":"Real world:"},{"screen":"Stage 4: development","src":"i_o8C5SxNCGaw.jpg","pack":"M3U4","w":820,"h":548,"alt":"A man working on a piece of wood with tools.","cap":"A craftsman turns a design into a finished object by building it piece by piece. In the development stage, programmers do the same, building the system from the design specification.","by":"Samuel Cruz","title":"Real world:"},{"screen":"Testing: verification, validation and the test report","src":"i_UWU_i03dNq4.jpg","pack":"M3U4","w":820,"h":547,"alt":"A technician examining equipment and recording observations.","cap":"A technician inspects equipment and records the findings. Testing a system works the same way, with results written up in a test report.","by":"TECNIC Bioprocess Solutions","title":"Real world:"},{"screen":"Stage 5: implementation and the conversion plan","src":"i_3kc_75Rdgyk.jpg","pack":"M3U4","w":820,"h":462,"alt":"A man standing in front of a seated group, speaking to them.","cap":"Introducing a new system means preparing the people who will use it. Implementation includes training users and following a conversion plan that moves the organisation from the old way of working to the new.","by":"Herlambang Tinasih Gusti","title":"Real world:"},{"screen":"Changeover methods: direct, parallel, phased, pilot","src":"i_rYzjlG45K1A.jpg","pack":"M3U4","w":820,"h":548,"alt":"Road closed and detour signs with traffic cones.","cap":"A road closed sign with a detour shows a changeover. Direct, parallel, phased and pilot methods each manage how traffic moves from the old system to the new.","by":"John Cardamone","title":"Real world:"},{"screen":"Documentation: user and technical manuals","src":"i_yjYxtxLOiF4.jpg","pack":"M3U4","w":820,"h":615,"alt":"Open cookbooks laid out on a table.","cap":"Open books show printed guidance. A user manual teaches people how to operate a system, while a technical manual helps staff maintain it.","by":"Annie Spratt","title":"Real world:"},{"screen":"Stage 6: review (evaluation and maintenance)","src":"i_bEGTsOCnHro.jpg","pack":"M3U4","w":820,"h":462,"alt":"A mechanic inspecting the engine of a car.","cap":"A mechanic inspects an engine to see how it is running. Review does the same for a system, evaluating it and then carrying out maintenance.","by":"Kate Ibragimova","title":"Real world:"},{"screen":"Worked case: one project from start to finish","src":"i_nMyM7fxpokE.jpg","pack":"M3U4","w":820,"h":558,"alt":"A hospital lobby with a reception desk and signs.","cap":"A busy reception area where appointments and records are handled. A worked case follows one project like this, from the first problem to the final review.","by":"Martha Dominguez de Gouveia","title":"Real world:"},{"screen":"Extension: four ways to obtain a system","src":"i_lcI46gCA_6U.jpg","pack":"M3U4","w":820,"h":547,"alt":"Inside a tailor's shop with fabrics and sewing equipment.","cap":"A tailor can make a garment to measure, buy one ready-made or adapt an existing one. In the same way, an organisation can develop a system in-house, buy off the shelf, customise it or outsource it.","by":"Zainab Iqbal","title":"Real world:"},{"screen":"Lecture notes: the SDLC and software engineering","src":"i_LyZO-6jLa8c.jpg","pack":"M3U4","w":820,"h":465,"alt":"A person walking up a staircase.","cap":"Climbing a staircase is a good picture of the stages of the SDLC, where each step builds on the one before and software engineering supplies the method.","by":"Vidar Nordli-Mathisen","title":"Real world:"}],"M3U5":[{"screen":"Class slides: The System Development Life Cycle","src":"i_YfCVCPMNd38.jpg","pack":"M3U5","w":820,"h":615,"alt":"A spiral staircase seen from above.","cap":"A spiral staircase leads round and back to where it began. The System Development Life Cycle is a cycle too, because review often leads to a new project.","by":"Ludde Lorentz","title":"Real world:"},{"screen":"A toolbox for every stage","src":"i_WdNEj127Zxc.jpg","pack":"M3U5","w":820,"h":547,"alt":"A variety of hand tools laid out on a table.","cap":"A workshop table holds different tools for different jobs. In the same way, analysts choose different tools at each stage of the life cycle, from fact-finding to design.","by":"Anton Savinov","title":"Real world:"},{"screen":"Fact-finding tool 1: interviews","src":"i_-P7kHROe-6A.jpg","pack":"M3U5","w":820,"h":565,"alt":"Two people sitting facing each other in an interview.","cap":"An interview is a face-to-face conversation in which one person asks questions and listens. Analysts use it as a fact-finding tool to learn how users do their work and what they need.","by":"Mina Rad","title":"Real world:"},{"screen":"Fact-finding tool 2: questionnaires","src":"i_g4WinrGsMl0.jpg","pack":"M3U5","w":820,"h":547,"alt":"A person holding a pen over a sheet of paper.","cap":"A person filling in a paper form is answering a set of written questions. A questionnaire collects facts from many people at once, making it a useful fact-finding tool.","by":"Jessica Lewis thepaintedsquare","title":"Real world:"},{"screen":"Fact-finding tools 3 and 4: observation and printed material","src":"i_Kx3o6_m1Yv8.jpg","pack":"M3U5","w":820,"h":547,"alt":"A man at a shop counter buying an item.","cap":"Watching a customer at a shop counter shows how a process really happens. Observation lets an analyst see actual work, while printed material such as receipts and forms provides further evidence.","by":"Blake Wisz","title":"Real world:"},{"screen":"Fact-finding tool 5: focus groups, and specifying requirements","src":"i_QiIxg_q2vh0.jpg","pack":"M3U5","w":820,"h":461,"alt":"A group of people seated around a table discussing.","cap":"A group discussion around a table. A focus group gathers users to share views, and the outcomes feed into the requirements specification.","by":"Zainul Yasni","title":"Real world:"},{"screen":"Choosing and combining fact-finding tools","src":"i_75EcEMrXgtg.jpg","pack":"M3U5","w":820,"h":462,"alt":"A signpost with several arrows pointing different ways.","cap":"A signpost with several directions. Analysts choose among fact-finding tools and often combine them, as each points to a different part of the answer.","by":"Boitumelo","title":"Real world:"},{"screen":"Modelling data: ER diagrams and DFDs","src":"i_TMk-J97rLro.jpg","pack":"M3U5","w":820,"h":547,"alt":"A wall of numbered drawers.","cap":"Numbered drawers hold items that are identified and linked by a key. An ER diagram models stored data in this way, and a DFD shows how data moves.","by":"Diego Marín","title":"Real world:"},{"screen":"Process models and object models","src":"i_sczNLg6rrhQ.jpg","pack":"M3U5","w":820,"h":547,"alt":"Stacked plastic boxes of different sizes.","cap":"Boxes of different types, each with its own contents. Object models describe a system as things like these, while process models show the steps.","by":"Adrian Sulyok","title":"Real world:"},{"screen":"Decision tables: structure and building one","src":"i_WLb70FexOYw.jpg","pack":"M3U5","w":820,"h":615,"alt":"A road junction controlled by traffic lights.","cap":"Traffic lights follow rules: if the light is red, stop. A decision table lists conditions and the actions that follow, in the same way.","by":"viktor rejent","title":"Real world:"},{"screen":"Decision trees, and tables versus trees","src":"i_0kbNh7XrJ7Q.jpg","pack":"M3U5","w":820,"h":462,"alt":"Two yellow signs pointing in opposite directions on a trail.","cap":"Signs on a trail send walkers one way or another. A decision tree branches in the same fashion, and each path leads to a different outcome.","by":"Marco Kaufmann","title":"Real world:"},{"screen":"Design tools: data dictionary and structured English","src":"i_U3Ptj3jafX8.jpg","pack":"M3U5","w":820,"h":547,"alt":"An open dictionary with printed entries.","cap":"A dictionary defines each word in a standard format. A data dictionary does the same for a system, recording the name, type and meaning of every data item so everyone uses the same definitions.","by":"Waldemar Brandt","title":"Real world:"},{"screen":"Gantt charts: planning and reading","src":"i_FoKO4DpXamQ.jpg","pack":"M3U5","w":820,"h":549,"alt":"A monthly planner on a desk.","cap":"A monthly planner shows tasks across time. A Gantt chart presents a project plan as bars on a timeline, so you can read start dates, durations and overlaps.","by":"Eric Rothermel","title":"Real world:"},{"screen":"CASE tools","src":"i_60krlMMeWxU.jpg","pack":"M3U5","w":820,"h":547,"alt":"A mechanic's tools arranged on a surface.","cap":"A mechanic works faster with the right tools. CASE tools are software that help analysts and programmers design, build and document systems.","by":"Quilia","title":"Real world:"},{"screen":"Three types of CASE tools","src":"i_lDwKKjlHL2Y.jpg","pack":"M3U5","w":820,"h":547,"alt":"Tools hanging in order on a workshop wall.","cap":"Tools sorted by purpose on a wall. CASE tools come in three types, each suited to a different part of the work.","by":"Anton Savinov","title":"Real world:"},{"screen":"CASE tool categories: tools and use cases","src":"i_jcav1COVvOc.jpg","pack":"M3U5","w":820,"h":285,"alt":"Warehouse shelving in rows.","cap":"Shelving sorted into rows by category. CASE tools are grouped in a similar way, with each category matched to use cases at different stages.","by":"Jacques Dillies","title":"Real world:"},{"screen":"Prototypes","src":"i_b1lMe6ughXc.jpg","pack":"M3U5","w":820,"h":462,"alt":"A white architectural scale model of a building.","cap":"A scale model lets people examine a design before the real building exists. A prototype of a system works the same way, allowing users to try it and suggest changes early.","by":"Salvus","title":"Real world:"},{"screen":"Flowcharts, pseudocode and programming languages","src":"i_3ovnpUMs5qM.jpg","pack":"M3U5","w":820,"h":615,"alt":"A kitchen counter with a mixer, fruit and recipe books.","cap":"A recipe is a set of steps, just like an algorithm. Flowcharts and pseudocode plan those steps, and a programming language then carries them out.","by":"Annie Spratt","title":"Real world:"},{"screen":"Development and testing tools","src":"i_3GZi6OpSDcY.jpg","pack":"M3U5","w":820,"h":547,"alt":"Circuit boards on a bench near a tester.","cap":"Circuit boards on a test bench. Development and testing tools help programmers build components and check that each one works.","by":"Nicolas Thomas","title":"Real world:"},{"screen":"Tools across the whole life cycle","src":"i_iUisLzp0F7M.jpg","pack":"M3U5","w":820,"h":544,"alt":"A craftsman's tools on a wooden board.","cap":"A craftsman's full set of tools for every task. Likewise, analysts use different tools at each stage across the whole life cycle.","by":"Konstantin Evdokimov","title":"Real world:"},{"screen":"Lecture notes: tools used in the SDLC","src":"i__u95HlNoz68.jpg","pack":"M3U5","w":820,"h":615,"alt":"A multimeter used to measure a circuit.","cap":"A multimeter measures and checks a circuit. Many tools used in the SDLC play the same role, measuring, checking and recording how a system performs.","by":"Mark Kats","title":"Real world:"}],"M3U6":[{"screen":"What is a data flow diagram? [SO 3.8]","src":"i_r3R6KYnG8pI.jpg","pack":"M3U6","w":820,"h":615,"alt":"An aerial view of a highway intersection at night.","cap":"A highway interchange from above shows routes and movement. A data flow diagram shows the same for data, tracing it from place to place through a system.","by":"Justin Zhu","title":"Real world:"},{"screen":"The four Gane and Sarson symbols","src":"i_qcIkeYYALT4.jpg","pack":"M3U6","w":820,"h":547,"alt":"A pole carrying many different signs.","cap":"Each sign on this pole has its own meaning. Gane and Sarson symbols work like signs, with four shapes that each mean something different.","by":"Astrid Schaffner","title":"Real world:"},{"screen":"External entities: sources and sinks","src":"i_Ox6SW103KtM.jpg","pack":"M3U6","w":820,"h":548,"alt":"A man smiling at a woman across a counter.","cap":"At a service counter, a customer is an outside party who gives information to the business and receives something back. In a data flow diagram, such outside people are external entities, acting as sources or sinks of data.","by":"Clay Banks","title":"Real world:"},{"screen":"Processes: where data is transformed","src":"i_RjKsSwQ-_Mg.jpg","pack":"M3U6","w":820,"h":593,"alt":"A person operating a machine.","cap":"A person operates a machine and turns inputs into output. A process in a DFD transforms incoming data into new data in the same way.","by":"Elshan Neymatov","title":"Real world:"},{"screen":"Data stores and data flows","src":"i_VnMbc9Szs-E.jpg","pack":"M3U6","w":820,"h":547,"alt":"A warehouse with boxes and pallets.","cap":"A warehouse keeps goods until needed, as a data store holds data until a process needs it. Data flows are the movement of goods in and out.","by":"Arum Visuals","title":"Real world:"},{"screen":"The context level DFD","src":"i_oYMg1_VxlaM.jpg","pack":"M3U6","w":820,"h":554,"alt":"A group of people standing in front of a counter.","cap":"People at a service counter see only the service, not what goes on behind it. A context diagram likewise shows the system as one process, with entities around it.","by":"Kyle Smith","title":"Real world:"},{"screen":"Worked example: ferry booking context diagram","src":"i_mVLEcDBRWnU.jpg","pack":"M3U6","w":820,"h":547,"alt":"People boarding a yellow ferry at a dock.","cap":"Passengers boarding a ferry are the customers of a booking system. In the context diagram, they are an external entity sending requests and receiving tickets.","by":"You Le","title":"Real world:"},{"screen":"The level 1 detailed DFD","src":"i_QHZrATU9ONM.jpg","pack":"M3U6","w":820,"h":547,"alt":"Light trails of traffic on a highway with directional signs.","cap":"A road splits into many routes. A level 1 DFD splits the single context process into its main processes, showing the data moving between them.","by":"Oliver Bornhauser","title":"Real world:"},{"screen":"Worked example: a payroll level 1 DFD","src":"i_fs59clk5ysA.jpg","pack":"M3U6","w":820,"h":547,"alt":"Four people travelling together in a blue boat on open water","cap":"Four people travel together in one boat. In a payroll DFD, data likewise travels between fixed points: timesheets flow from employees into the process, and pay slips flow back out to them.","by":"Sergio Aguirre","title":"Real world:"},{"screen":"The rules of a correct DFD","src":"i_IPeGLFSyhzg.jpg","pack":"M3U6","w":820,"h":547,"alt":"Hands writing on a sheet of paper attached to a clipboard","cap":"Hands fill in a form on a clipboard, checking each entry as they go. A correct DFD is checked in the same way, against fixed rules such as labelling every flow and process.","by":"Zulfugar Karimov","title":"Real world:"},{"screen":"DFD errors 1: black holes and miracles","src":"i_Gw5soLegtdw.jpg","pack":"M3U6","w":820,"h":615,"alt":"Churning water forming a whirlpool","cap":"A whirlpool pulls water in with no visible way out. A black hole in a DFD is similar: a process that receives data inputs but produces no output flows.","by":"Mike CruX","title":"Real world:"},{"screen":"DFD errors 2: illegal connections and labels","src":"i_ynFrMaSiau8.jpg","pack":"M3U6","w":820,"h":548,"alt":"Chain-link fence secured with a padlock","cap":"A padlocked fence allows only certain connections. A DFD has the same kind of restriction: some connections, such as data flowing directly between two external entities, are illegal and must be removed.","by":"Lucas van Oort","title":"Real world:"},{"screen":"Describing a DFD in words","src":"i_5Q07sS54D0Q.jpg","pack":"M3U6","w":820,"h":615,"alt":"Person writing diagrams on a glass whiteboard","cap":"A person sketches a diagram on a whiteboard to explain an idea. Describing a DFD in words does the same job in reverse, turning the boxes and arrows into sentences.","by":"Kvalifik","title":"Real world:"},{"screen":"Lecture notes: data flow diagrams","src":"i_kGix6_gPKjI.jpg","pack":"M3U6","w":820,"h":462,"alt":"Water flowing through a bamboo tube","cap":"Water moves along a bamboo tube from one place to another. A data flow diagram shows data moving in the same way, along labelled paths between processes, stores and external entities.","by":"Arseny Togulev","title":"Real world:"}],"M3U7":[{"screen":"What is an algorithm?","src":"i_4nk7VPj_m6g.jpg","pack":"M3U7","w":820,"h":547,"alt":"Woman chopping vegetables on a board in a kitchen","cap":"A cook prepares vegetables, one step in a recipe. A recipe is an everyday algorithm: a set of ordered instructions that turns inputs (ingredients) into a result (a meal).","by":"Douglas Fehr","title":"Real world:"},{"screen":"An algorithm as a problem-solving strategy","src":"i_R0kqnphnQfs.jpg","pack":"M3U7","w":820,"h":547,"alt":"People finding their way through a hedge maze.","cap":"Finding the way through a maze needs a clear strategy. An algorithm is a step-by-step strategy for solving a problem, and following it carefully leads from the start to the solution.","by":"Lv Bowen","title":"Real world:"},{"screen":"The role and importance of algorithms","src":"i_eBi0v1D_po8.jpg","pack":"M3U7","w":820,"h":547,"alt":"An escalator inside a station.","cap":"An escalator follows one fixed, repeatable routine every time it is used. Algorithms matter in the same way, because computers rely on precise procedures that give consistent results.","by":"Teemu Laukkarinen","title":"Real world:"},{"screen":"Characteristics: a general solution in a finite number of steps","src":"i_O-wRrxy-evo.jpg","pack":"M3U7","w":820,"h":547,"alt":"Measuring glass containing flour in a kitchen","cap":"A measuring glass holds flour for a recipe. A recipe works for any quantity if the amounts are scaled, just as a general algorithm solves any case of a problem and ends after a finite number of steps.","by":"Morgane Perraud","title":"Real world:"},{"screen":"Characteristics: unambiguous steps and flow of control","src":"i_bd7HCEl1PVQ.jpg","pack":"M3U7","w":820,"h":547,"alt":"A woman assembling a wooden rack.","cap":"Assembly instructions for flat-pack furniture list steps that must be clear and in the right order. An algorithm needs the same: unambiguous steps and a definite flow of control from start to finish.","by":"David Schultz","title":"Real world:"},{"screen":"Worked example: improving a poorly designed algorithm","src":"i_hxVwlrOkP3c.jpg","pack":"M3U7","w":820,"h":547,"alt":"Takeaway lunch of sliced brown-stew fish with macaroni salad, rice and peas","cap":"A takeaway lunch of brown-stew fish, macaroni salad, rice and peas. Ordering this meal at a canteen involves clear steps; if the steps are vague or out of order, the algorithm must be improved.","by":"Gabre Cameron","title":"Real world:"},{"screen":"Three ways of representing an algorithm","src":"i_n8rK2ALPHTY.jpg","pack":"M3U7","w":820,"h":547,"alt":"Open book of sheet music with musical notes","cap":"Sheet music records a tune in a standard notation that anyone can follow. An algorithm can likewise be recorded in more than one notation: natural language, a flowchart or pseudocode.","by":"Tommy Diner","title":"Real world:"},{"screen":"Natural language","src":"i_h6FvuGNCnqA.jpg","pack":"M3U7","w":820,"h":596,"alt":"Parking meter displaying the words Time Expired","cap":"A parking meter shows the plain words \"Time Expired\". Natural language is easy to read like this, but long instructions written in everyday words can become wordy or open to different interpretations.","by":"John Cardamone","title":"Real world:"},{"screen":"Flowcharts: the standard symbols","src":"i_3ykTik-GPEc.jpg","pack":"M3U7","w":820,"h":547,"alt":"Illuminated subway maps with coloured lines and station symbols.","cap":"A transport map uses standard symbols and coloured lines so anyone can follow a route. A flowchart does this for an algorithm, using standard shapes joined by arrows to show the order of steps.","by":"Angelica Hasbon","title":"Real world:"},{"screen":"Reading a flowchart: following the flow of control","src":"i_Jh14Mk3U_ws.jpg","pack":"M3U7","w":820,"h":461,"alt":"Dirt road splitting into two paths","cap":"A dirt road splits into two paths. Reading a flowchart means following one path at each decision point, and the answer to a yes or no question decides which route you take.","by":"Cabbie Kqwi","title":"Real world:"},{"screen":"Pseudocode: structured English for programmers","src":"i_RdmLSJR-tq8.jpg","pack":"M3U7","w":820,"h":547,"alt":"A notebook with handwritten notes and a pen on a desk.","cap":"Handwritten notes planning a task in plain, ordered statements show the idea behind pseudocode. It describes an algorithm in structured English before it is written in a programming language.","by":"Thought Catalog","title":"Real world:"},{"screen":"One problem, three representations: the water taxi fare","src":"i_N9cLMx0ipRM.jpg","pack":"M3U7","w":820,"h":489,"alt":"Yellow water taxi on a river beside tall buildings","cap":"A water taxi carries passengers along a river. Working out its fare is a problem that can be written as natural language, drawn as a flowchart or set out in pseudocode.","by":"Deborah L Carlson","title":"Real world:"},{"screen":"Comparing natural language, flowcharts and pseudocode","src":"i_yg8Cz-i5U30.jpg","pack":"M3U7","w":820,"h":547,"alt":"Close-up of a printed route map","cap":"A route map shows a journey as a picture, while directions can also be written in words. Flowcharts are the visual form of an algorithm, and natural language and pseudocode are the written forms.","by":"Stephen Monroe","title":"Real world:"},{"screen":"Lecture notes: algorithms, design and representation","src":"i_eS_Y2MFncjo.jpg","pack":"M3U7","w":820,"h":593,"alt":"A woman stirring a pot on a stove.","cap":"A recipe is an everyday algorithm: a set of ordered steps that turns ingredients into a meal. Algorithms in computing are designed and represented in the same way, using flowcharts or pseudocode.","by":"Douglas Fehr","title":"Real world:"}],"M3U8":[{"screen":"The building blocks of an algorithm","src":"i_RcxR1aLw8X0.jpg","pack":"M3U8","w":820,"h":615,"alt":"Assorted-colour wooden blocks","cap":"Wooden blocks combine into larger structures. Every algorithm is built in the same way from a few basic blocks: sequence, selection and repetition.","by":"Michał Bożek","title":"Real world:"},{"screen":"Flowchart symbols and the three control structures","src":"i_kvSOLfp56uo.jpg","pack":"M3U8","w":820,"h":615,"alt":"Aerial view of a traffic roundabout with roads leading off it","cap":"An aerial view of a roundabout, where traffic either exits or goes round again. A flowchart shows the same kinds of paths: a straight sequence, a branch for selection and a loop for repetition.","by":"Héctor Emilio Gonzalez","title":"Real world:"},{"screen":"Sequence: step by step, in order","src":"i_3iZ5u1rEEr8.jpg","pack":"M3U8","w":820,"h":547,"alt":"Refrigerators moving along a factory assembly line, long exposure","cap":"Refrigerators move along a factory assembly line, passing each stage in turn. Sequence in an algorithm works like this: each step is carried out once, in the order written.","by":"Homa Appliances","title":"Real world:"},{"screen":"Selection: IF-THEN and IF-THEN-ELSE","src":"i_a44vcW7o_RM.jpg","pack":"M3U8","w":820,"h":547,"alt":"Sunlit forest path with a wooden signpost at a trail intersection","cap":"A signpost at a trail intersection means walkers must choose a direction. Selection (IF-THEN-ELSE) does the same: a condition is tested and the algorithm takes one route or the other.","by":"Jake Banasik","title":"Real world:"},{"screen":"Arithmetic and order of precedence in conditions","src":"i_i3rBo3b9QbA.jpg","pack":"M3U8","w":820,"h":547,"alt":"A wooden abacus with coloured beads.","cap":"An abacus is a simple calculating tool where beads stand for numbers. Computers also evaluate arithmetic using fixed rules, so operators such as multiplication and division are worked out before addition and subtraction.","by":"Kati Hoehl","title":"Real world:"},{"screen":"Repetition I: the FOR loop (counting up and down)","src":"i_xAkb7RuKmTw.jpg","pack":"M3U8","w":820,"h":548,"alt":"A woman riding an escalator.","cap":"An escalator carries a person up and then down again by repeating the same motion. A FOR loop repeats steps in the same way, counting up or down for a set number of times.","by":"Caesar Aldhela","title":"Real world:"},{"screen":"Repetition II: WHILE and REPEAT-UNTIL","src":"i_-yjUzBUqVTU.jpg","pack":"M3U8","w":820,"h":409,"alt":"People standing in a line waiting","cap":"People wait in a line until it is their turn. A WHILE or REPEAT-UNTIL loop likewise keeps repeating until a condition changes, and the number of repeats is not fixed in advance.","by":"Dominic Kurniawan Suryaputra","title":"Real world:"},{"screen":"Counters and accumulators","src":"i_lRD3hFTKtmk.jpg","pack":"M3U8","w":820,"h":547,"alt":"Black digital device displaying the number 87","cap":"A digital display shows a running number. A counter in an algorithm works like this, increasing by one each time, while an accumulator keeps a running total of values added to it.","by":"Artem Xromov","title":"Real world:"},{"screen":"Trace tables: dry-running an algorithm","src":"i_q3blHqtnhog.jpg","pack":"M3U8","w":820,"h":534,"alt":"Open notebook with a pencil resting on the page","cap":"A pencil and an open notebook are ready to record values by hand. A trace table is filled in in this way, row by row, to dry-run an algorithm and see each variable change.","by":"Kelly Sikkema","title":"Real world:"},{"screen":"Tracing loops that contain IF-THEN-ELSE","src":"i_gNfWMNwyV6A.jpg","pack":"M3U8","w":820,"h":615,"alt":"Aerial view of a car on a rural roundabout","cap":"A car reaches a roundabout and must choose an exit each time round. Tracing a loop that contains IF-THEN-ELSE means recording which branch is taken on every pass.","by":"Bernd Dittrich","title":"Real world:"},{"screen":"Developing a complete algorithm: a Caribbean problem","src":"i_0MKzwPmehRE.jpg","pack":"M3U8","w":820,"h":547,"alt":"Black and white electric meter","cap":"An electric meter records the units of electricity used. Working out a bill from a reading, with different rates at different usage levels, is a practical problem an algorithm can solve.","by":"Jon Moore","title":"Real world:"},{"screen":"Algorithms as the precursor to program development","src":"i_3ym6i13Y9LU.jpg","pack":"M3U8","w":820,"h":560,"alt":"Pen resting on a blank sketchbook","cap":"A pen lies on a blank sketchbook, ready for a design to be drawn. An algorithm is the sketch that comes before the program, planned on paper before any code is written.","by":"Mike Tinnion","title":"Real world:"},{"screen":"Developing computer programs: the stages","src":"i_sNVkn3507Oo.jpg","pack":"M3U8","w":820,"h":615,"alt":"Two men in hard hats pointing at a construction site with scaffolding","cap":"Two workers in hard hats review a building site with scaffolding. Building software also moves through planned stages, from analysis and design to coding, testing and maintenance.","by":"Mark Potterton","title":"Real world:"},{"screen":"Programming paradigms","src":"i_GkZoz3gVG8c.jpg","pack":"M3U8","w":820,"h":544,"alt":"Paint brushes of different sizes in a container.","cap":"Painters choose different brushes for different jobs and styles. Programmers likewise choose different paradigms, such as procedural or object-oriented, as different approaches to writing code.","by":"Debby Hudson","title":"Real world:"},{"screen":"Lecture notes: Developing algorithms and programming","src":"i_bZ_RkRKE0Po.jpg","pack":"M3U8","w":820,"h":547,"alt":"Woman turning the page of a book","cap":"A reader turns the page of a book, moving on to the next section. Revising these notes follows the same path, from designing algorithms to developing programs.","by":"Alissa De Leva","title":"Real world:"}]};
/* Notes photographs and real-world colour examples.
   Every notes screen gets a captioned real photograph; colour theory and colour psychology screens also get
   in-depth "Real-world example" panels: a real photo, the palette measured from it (hex codes and share of the image)
   and an analysis linked to the notes. Images are stored inside the course. Kester Small. */
(function () {
  'use strict';
  const P = window.COURSE_NOTE_PHOTOS || {};
  const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  function css() {
    if (document.getElementById('nph-css')) return;
    const s = document.createElement('style'); s.id = 'nph-css';
    s.textContent = `
.nph{clear:both;margin:16px 0 18px;padding:9px;border-radius:16px;background:var(--raise,rgba(255,255,255,.05));border:1px solid var(--line,rgba(245,197,66,.3));box-shadow:0 10px 26px -12px rgba(0,0,0,.45);max-width:none}
.nph-ph{position:relative;display:block;width:100%;margin:0;padding:0;border:0;font:inherit;background:var(--surface,#0b1736);border-radius:11px;overflow:hidden;cursor:zoom-in}
.nph-ph img{display:block;width:100%;height:auto;aspect-ratio:var(--ar,3/2);object-fit:cover;max-height:min(480px,64vh)}
.nph-card .nph-ph img{max-height:340px}
.nph figcaption{margin-top:8px;font-size:.9rem;line-height:1.5}
.nph figcaption b{color:var(--gold,#F5C542)}
.nph .cr{display:block;margin-top:3px;font-size:.74rem;opacity:.75}
.nph-pal{display:flex;gap:4px;margin-top:8px;flex-wrap:wrap}
.nph-pal .sw{flex:1 1 60px;min-width:56px;border-radius:8px;overflow:hidden;border:1px solid var(--line,rgba(255,255,255,.2));background:var(--surface,#0b1736)}
.nph-pal .sw i{display:block;height:34px}
.nph-pal .sw span{display:block;padding:3px 5px;font:700 .7rem/1.25 ui-monospace,Menlo,Consolas,monospace;letter-spacing:.02em}
.nph-pal .sw small{display:block;font-weight:400;opacity:.75;font-family:var(--f-body,inherit)}
.nph-bar{display:flex;height:12px;border-radius:99px;overflow:hidden;margin-top:6px;border:1px solid var(--line,rgba(255,255,255,.2))}
.nph-bar i{display:block;height:100%}
.nph-ex{clear:both;margin:22px 0 10px;display:flex;flex-direction:column;gap:14px}
.nph-ex>h3{display:flex;align-items:center;gap:8px;font-size:1.2rem}
.nph-ex>h3::before{content:'';width:22px;height:22px;border-radius:50%;flex:none;background:conic-gradient(#E53935,#FDD835,#43A047,#1E88E5,#8E24AA,#E53935)}
.nph-ex>.lead{opacity:.9}
.nph-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}
.nph-card{display:flex;flex-direction:column;gap:9px;padding:10px;border-radius:16px;background:var(--raise,rgba(255,255,255,.05));border:1px solid var(--line,rgba(245,197,66,.3));box-shadow:0 10px 26px -12px rgba(0,0,0,.45);min-width:0}
.nph-card.wide{grid-column:1/-1}
.nph-card.wide .in{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:14px;align-items:start}
@media (max-width:700px){.nph-card.wide .in{grid-template-columns:minmax(0,1fr)}}
.nph-card .tag{align-self:flex-start;font-size:.7rem;font-weight:700;letter-spacing:.09em;text-transform:uppercase;padding:3px 10px;border-radius:99px;background:var(--soft-gold,rgba(255,215,102,.16))}
.nph-card h4{font-size:1.05rem}
.nph-card .an{display:flex;flex-direction:column;gap:7px;font-size:.93rem;line-height:1.55}
.nph-card .an p{margin:0}
.nph-card .an ul{margin:0}
.nph-card .q{margin-top:2px;padding:8px 11px;border-radius:10px;background:var(--soft-blue,rgba(245,197,66,.14));font-weight:400;font-size:.9rem}
.nph-card .q b{font-weight:700}
.nph-full{position:fixed;inset:0;z-index:80;background:rgba(3,6,18,.9);display:grid;place-items:center;padding:16px}
.nph-full figure{margin:0;max-width:min(1100px,100%);max-height:100%;display:flex;flex-direction:column;gap:8px;color:#fff}
.nph-full img{max-width:100%;max-height:calc(100vh - 140px);object-fit:contain;border-radius:10px;margin:0 auto}
.nph-full figcaption{font-size:.92rem;text-align:center}
.nph-full button{align-self:center}
.html-body.ufig-host .nph,.html-body.ufig-host .nph-ex{clear:both}
.hexchip{display:inline-flex;align-items:center;gap:4px;padding:0 6px 0 3px;border-radius:6px;background:var(--surface,rgba(0,0,0,.2));border:1px solid var(--line,rgba(255,255,255,.2));font:700 .78em/1.6 ui-monospace,Menlo,Consolas,monospace;white-space:nowrap;vertical-align:baseline}
.hexchip i{width:.95em;height:.95em;border-radius:3px;background:var(--c);border:1px solid rgba(127,127,127,.5)}`;
    document.head.appendChild(s);
  }
  function pal(p, bar) {
    if (!p || !p.length) return '';
    const sw = p.map(c => `<div class="sw" title="${esc(c[0])}"><i style="background:${esc(c[0])}"></i><span>${esc(c[0].toUpperCase())}${c[2] ? `<small>${esc(c[2])}</small>` : ''}<small>${c[1]}% of photo</small></span></div>`).join('');
    const tot = p.reduce((a, c) => a + (+c[1] || 0), 0) || 1;
    const b = bar ? `<div class="nph-bar" aria-hidden="true">${p.map(c => `<i style="background:${esc(c[0])};width:${(100 * c[1] / tot).toFixed(1)}%"></i>`).join('')}</div>` : '';
    return `<div class="nph-pal" role="list" aria-label="Colour palette measured from the photo">${sw}</div>${b}`;
  }
  const SRC = f => f.pack ? ((window.__nphImg || {})[f.src] || '') : f.src;
  const packs = {};
  function need(list) {
    const miss = [...new Set(list.filter(f => f.pack && !(window.__nphImg || {})[f.src]).map(f => f.pack))];
    miss.forEach(p => { if (packs[p]) return; packs[p] = 1; const s = document.createElement('script'); s.src = 'img/notes/' + p + '.js'; s.onload = () => { const b = document.querySelector('#stage .html-body'); if (b) b.querySelectorAll('.nph,.nph-ex').forEach(e => e.remove()); kick(); }; s.onerror = () => { packs[p] = 0; }; document.head.appendChild(s); });
    return miss.length;
  }
  function img(f, k) {
    return `<button type="button" class="nph-ph" data-nphz="${k}" aria-label="Enlarge photo" style="--ar:${f.w}/${f.h}"><img src="${esc(SRC(f))}" alt="${esc(f.alt)}" width="${f.w}" height="${f.h}" loading="lazy" decoding="async"></button>`;
  }
  function photo(f, k) {
    return `<figure class="nph" data-nph="${k}">${img(f, k)}${f.pal ? pal(f.pal) : ''}<figcaption><b>${esc(f.title || 'Photo')}</b> ${esc(f.cap)}<span class="cr">Photo: ${esc(f.by)}</span></figcaption></figure>`;
  }
  function card(f, k) {
    const body = `<div class="an">${f.html || ''}</div>${f.q ? `<div class="q"><b>Try it:</b> ${f.q}</div>` : ''}<span class="cr" style="font-size:.74rem;opacity:.75">Photo: ${esc(f.by)}</span>`;
    const pic = `${img(f, k)}${pal(f.pal, true)}`;
    return `<article class="nph-card${f.wide ? ' wide' : ''}">${f.tag ? `<span class="tag">${esc(f.tag)}</span>` : ''}<h4>${esc(f.title || '')}</h4>${f.wide ? `<div class="in"><div>${pic}</div><div>${body}</div></div>` : pic + body}</article>`;
  }
  function cur() {
    try {
      const A = window.COURSE_API, L = (A && A.S && A.S.loc) || {};
      let v = L.v, m = L.m, u = L.u, s = L.s;
      if (!v) { const p = new URLSearchParams(String(location.hash || '').replace(/^#/, '')); v = p.get('v'); m = p.get('m'); u = p.get('u'); s = p.get('s'); }
      if (v !== 'screen') return null;
      const M = (window.COURSE_MODULES || []).find(x => x.id === m); if (!M) return null;
      const U = M.units[+u]; if (!U) return null; const S = U.screens[s == null ? 0 : +s]; if (!S || S.type !== 'learn') return null;
      return { U, S };
    } catch (e) { return null; }
  }
  let curList = [];
  function inject() {
    const c = cur(); if (!c) return;
    const body = document.querySelector('#stage article.card .html-body') || document.querySelector('#stage .card .html-body');
    if (!body || body.querySelector('.nph,.nph-ex')) return;
    const all = (P[c.U.id] || []).filter(f => f.screen === c.S.title); if (!all.length) return;
    if (need(all)) return;
    css(); curList = all;
    const ph = all.filter(f => f.kind !== 'example'), ex = all.filter(f => f.kind === 'example');
    if (ph.length) {
      const html = ph.map(f => photo(f, all.indexOf(f))).join('');
      const kids = [...body.children].filter(e => !e.classList.contains('ufig'));
      const firstP = kids.find(e => e.tagName === 'P' && (e.textContent || '').trim().length > 40);
      if (firstP) firstP.insertAdjacentHTML('afterend', html); else body.insertAdjacentHTML('afterbegin', html);
    }
    if (ex.length) {
      const intro = ex[0].intro || 'Each photo below is a real scene. The swatches show the main colours measured from the photo, with their hex codes and how much of the image each one covers.';
      const html = `<section class="nph-ex" aria-label="Real-world colour examples"><h3>Real-world examples</h3><p class="lead">${intro}</p><div class="nph-grid">${ex.map(f => card(f, all.indexOf(f))).join('')}</div></section>`;
      const tip = [...body.children].reverse().find(e => e.classList && e.classList.contains('tip'));
      const fig = body.querySelector('.nfig');
      if (fig) fig.insertAdjacentHTML('beforebegin', html); else if (tip) tip.insertAdjacentHTML('beforebegin', html); else body.insertAdjacentHTML('beforeend', html);
    }
  }
  document.addEventListener('click', e => {
    const z = e.target.closest && e.target.closest('[data-nphz]'); if (!z) return;
    const f = curList[+z.dataset.nphz]; if (!f) return;
    const ov = document.createElement('div'); ov.className = 'nph-full'; ov.setAttribute('role', 'dialog'); ov.setAttribute('aria-label', f.title || 'Photo');
    ov.innerHTML = `<figure><img src="${esc(SRC(f))}" alt="${esc(f.alt)}"><figcaption><b>${esc(f.title || '')}</b> ${esc(f.cap || '')}</figcaption><button type="button" class="btn gold">Close</button></figure>`;
    ov.addEventListener('click', ev => { if (ev.target === ov || ev.target.closest('button')) ov.remove(); });
    document.addEventListener('keydown', function k(ev) { if (ev.key === 'Escape') { ov.remove(); document.removeEventListener('keydown', k); } });
    document.body.appendChild(ov); const b = ov.querySelector('button'); if (b) b.focus();
  });
  let q = 0; const kick = () => { if (q) return; q = requestAnimationFrame(() => { q = 0; try { inject(); } catch (e) { } }); };
  window.addEventListener('hashchange', kick); window.addEventListener('popstate', kick);
  const start = () => { const st = document.getElementById('stage'); if (st) new MutationObserver(kick).observe(st, { childList: true, subtree: true }); kick(); };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else setTimeout(start, 0);
})();
